INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points) VALUES
('cfbe84ed-97ab-5176-a2a4-b6ce4856eeef', '34322ed1-8148-406d-97ee-947a4eca6b7f', '98bbfcc1-1e3c-5d99-be0d-e19121542f69', 'a-level', '23.1', '9702 coursebook 23.1 · Capacitors and capacitance', 9, 9, 'Which expression defines the capacitance C of a capacitor?', NULL, 1, 'multiple_choice'::answer_type, 'C = Q/V, the charge on one plate divided by the p.d. between the plates', NULL, false, NULL, false, NULL, 'Capacitance is charge stored per unit potential difference. Mark scheme (1 mark). B1: C (C = Q/V, the charge on one plate divided by the p.d. between the plates).', 1),
('cff4695c-6825-5fe6-af53-137b2f69b0bf', '34322ed1-8148-406d-97ee-947a4eca6b7f', '98bbfcc1-1e3c-5d99-be0d-e19121542f69', 'a-level', '23.1', '9702 coursebook 23.1 · Capacitors and capacitance', 10, 10, 'Which unit is equivalent to the farad?', NULL, 1, 'multiple_choice'::answer_type, 'C V⁻¹', NULL, false, NULL, false, NULL, 'C = Q/V, so one farad is one coulomb stored per volt: 1 F = 1 C V⁻¹. Mark scheme (1 mark). B1: A (C V⁻¹).', 1),
('637b78d9-918d-5a41-964e-45f9fcaf44e5', '34322ed1-8148-406d-97ee-947a4eca6b7f', '98bbfcc1-1e3c-5d99-be0d-e19121542f69', 'a-level', '23.1', '9702 coursebook 23.1 · Capacitors and capacitance', 11, 11, 'A 470 µF capacitor in a camera flash circuit is connected to a 6.0 V battery. How much charge does it store, in mC?', NULL, 1, 'numeric'::answer_type, '2.82 mC', 'mC', false, NULL, false, NULL, 'Q = CV = 470 × 10⁻⁶ × 6.0 = 0.00282 C. In mC: 0.00282 × 1000 = 2.82. Mark scheme (2 marks). C1: Q = CV with C in F. A1: Q = 2.82 mC.', 2),
('a370ea7f-717d-5f65-bfc3-3d0d101dfa9a', '34322ed1-8148-406d-97ee-947a4eca6b7f', '98bbfcc1-1e3c-5d99-be0d-e19121542f69', 'a-level', '23.1', '9702 coursebook 23.1 · Capacitors and capacitance', 12, 12, 'A capacitor stores 1.5 mC of charge when the p.d. across it is 3.0 V. Calculate its capacitance in µF.', NULL, 1, 'numeric'::answer_type, '500', 'µF', false, NULL, false, ARRAY['5e-4']::text[], 'C = Q/V = 1.5 × 10⁻³ ÷ 3.0 = 5.0 × 10⁻⁴ F. In µF: 5.0 × 10⁻⁴ × 10⁶ = 500. Mark scheme (2 marks). C1: C = Q/V. A1: C = 500 µF.', 2),
('7d96b0f3-15b5-5b7a-8dee-d29ae5633276', '34322ed1-8148-406d-97ee-947a4eca6b7f', '98bbfcc1-1e3c-5d99-be0d-e19121542f69', 'a-level', '23.1', '9702 coursebook 23.1 · Capacitors and capacitance', 13, 13, 'A capacitor is charged so that one plate carries +Q. What is the charge on the other plate?', NULL, 1, 'multiple_choice'::answer_type, '−Q', NULL, false, NULL, false, NULL, 'Electrons removed from one plate are pushed onto the other, so the plates carry equal and opposite charges. Mark scheme (1 mark). B1: D (−Q).', 1),
('56e171c4-26e3-59b2-bf58-e7764c292cc3', '34322ed1-8148-406d-97ee-947a4eca6b7f', '98bbfcc1-1e3c-5d99-be0d-e19121542f69', 'a-level', '23.1', '9702 coursebook 23.1 · Capacitors and capacitance', 14, 14, 'A 2200 µF capacitor holds a charge of 0.033 C. Calculate the p.d. across it.', NULL, 1, 'numeric'::answer_type, '15', 'V', false, NULL, false, NULL, 'V = Q/C = 0.033 ÷ 2200 × 10⁻⁶ = 15 V. Mark scheme (2 marks). C1: V = Q/C. A1: V = 15 V.', 2),
('8f1401ff-24e2-50f9-a3f9-c67250d003a2', '34322ed1-8148-406d-97ee-947a4eca6b7f', '98bbfcc1-1e3c-5d99-be0d-e19121542f69', 'a-level', '23.1', '9702 coursebook 23.1 · Capacitors and capacitance', 15, 15, 'Which describes the graph of charge stored against p.d. for a capacitor?', NULL, 1, 'multiple_choice'::answer_type, 'A straight line through the origin, whose gradient is the capacitance', NULL, false, NULL, false, NULL, 'Q = CV, so Q ∝ V with gradient C. Mark scheme (1 mark). B1: B (A straight line through the origin, whose gradient is the capacitance).', 1),
('e5c5b3ae-5899-524e-844f-c208963b459a', '34322ed1-8148-406d-97ee-947a4eca6b7f', '98bbfcc1-1e3c-5d99-be0d-e19121542f69', 'a-level', '23.1', '9702 coursebook 23.1 · Capacitors and capacitance', 16, 16, 'While a capacitor is being charged by a battery, which statement is correct?', NULL, 1, 'multiple_choice'::answer_type, 'Electrons flow round the circuit from one plate to the other; none cross the insulating gap', NULL, false, NULL, false, NULL, 'The battery moves electrons off one plate and onto the other through the wires. Mark scheme (1 mark). B1: C (Electrons flow round the circuit from one plate to the other; none cross the insulating gap).', 1),
('0cbd9c3b-9352-5749-8814-adc4f7b6ef44', '34322ed1-8148-406d-97ee-947a4eca6b7f', '98bbfcc1-1e3c-5d99-be0d-e19121542f69', 'a-level', '23.1', '9702 coursebook 23.1 · Capacitors and capacitance', 17, 17, 'Express a capacitance of 4700 µF in farads.', NULL, 1, 'numeric'::answer_type, '0.0047', 'F', false, NULL, false, NULL, 'C = 4700 × 10⁻⁶ = 0.0047 F. Mark scheme (1 mark). A1: C = 0.0047 F.', 1),
('8f9d8e6f-76c4-51e3-a4e6-6e32f011fb2e', '34322ed1-8148-406d-97ee-947a4eca6b7f', '98bbfcc1-1e3c-5d99-be0d-e19121542f69', 'a-level', '23.1', '9702 coursebook 23.1 · Capacitors and capacitance', 18, 18, 'A capacitor is charged by a steady current of 2.0 mA for 5.0 s. Calculate the charge stored.', NULL, 1, 'numeric'::answer_type, '0.01', 'C', false, NULL, false, NULL, 'Q = It = 2.0 × 10⁻³ × 5.0 = 0.010 C. Mark scheme (2 marks). C1: Q = It. A1: Q = 0.010 C.', 2),
('3a589618-2602-51ce-88ae-055f68f334ab', '34322ed1-8148-406d-97ee-947a4eca6b7f', '98bbfcc1-1e3c-5d99-be0d-e19121542f69', 'a-level', '23.1', '9702 coursebook 23.1 · Capacitors and capacitance', 19, 19, 'The p.d. across a capacitor is doubled. What happens to the charge it stores?', NULL, 1, 'multiple_choice'::answer_type, 'It doubles', NULL, false, NULL, false, NULL, 'Q = CV and C is constant. Mark scheme (1 mark). B1: A (It doubles).', 1),
('411c1aac-61a8-55c5-ade2-9b9e4d30d664', '34322ed1-8148-406d-97ee-947a4eca6b7f', '98bbfcc1-1e3c-5d99-be0d-e19121542f69', 'a-level', '23.1', '9702 coursebook 23.1 · Capacitors and capacitance', 20, 20, 'A 10 µF capacitor stores 50 µC of charge. Calculate the p.d. across it.', NULL, 1, 'numeric'::answer_type, '5', 'V', false, NULL, false, NULL, 'V = Q/C = 50 × 10⁻⁶ ÷ 10 × 10⁻⁶ = 5.0 V. Mark scheme (2 marks). C1: V = Q/C. A1: V = 5.0 V.', 2),
('8a70b3f2-75bb-518f-82b9-bb637840e1f6', '34322ed1-8148-406d-97ee-947a4eca6b7f', '98bbfcc1-1e3c-5d99-be0d-e19121542f69', 'a-level', '23.1', '9702 coursebook 23.1 · Capacitors and capacitance', 21, 21, 'What is meant by a capacitance of one farad?', NULL, 1, 'multiple_choice'::answer_type, 'One coulomb of charge is stored for each volt of p.d.', NULL, false, NULL, false, NULL, 'C = Q/V: 1 F = 1 C V⁻¹. Mark scheme (1 mark). B1: D (One coulomb of charge is stored for each volt of p.d.).', 1),
('0d441f8a-409c-5dfb-afa8-ea80439fb676', '34322ed1-8148-406d-97ee-947a4eca6b7f', '98bbfcc1-1e3c-5d99-be0d-e19121542f69', 'a-level', '23.1', '9702 coursebook 23.1 · Capacitors and capacitance', 22, 22, 'What does the area under a graph of charging current against time represent?', NULL, 1, 'multiple_choice'::answer_type, 'The charge stored on the capacitor', NULL, false, NULL, false, NULL, 'Q = ∫I dt, the area under the I–t graph. Mark scheme (1 mark). B1: B (The charge stored on the capacitor).', 1),
('b6a535ff-6f8d-5bd5-b582-6c5104cda269', '34322ed1-8148-406d-97ee-947a4eca6b7f', '98bbfcc1-1e3c-5d99-be0d-e19121542f69', 'a-level', '23.1', '9702 coursebook 23.1 · Capacitors and capacitance', 23, 23, 'A capacitor is charged from zero by a constant current of 50 µA for 40 s, after which the p.d. across it is 8.0 V. Calculate its capacitance in µF.', NULL, 2, 'numeric'::answer_type, '250', 'µF', false, NULL, false, ARRAY['2.5e-4']::text[], 'Q = It = 50 × 10⁻⁶ × 40 = 2.0 × 10⁻³ C. C = Q/V = 2.0 × 10⁻³ ÷ 8.0 = 2.5 × 10⁻⁴ F. In µF: 2.5 × 10⁻⁴ × 10⁶ = 250. Mark scheme (3 marks). C1: Q = It. C1: C = Q/V. A1: C = 250 µF.', 3),
('6db58bd5-8275-5e78-8d87-c418c7cb3e9b', '34322ed1-8148-406d-97ee-947a4eca6b7f', '98bbfcc1-1e3c-5d99-be0d-e19121542f69', 'a-level', '23.1', '9702 coursebook 23.1 · Capacitors and capacitance', 24, 24, 'A camera-flash capacitor of 150 µF is charged to 330 V. Calculate the charge it stores, in mC.', NULL, 2, 'numeric'::answer_type, '49.5 mC', 'mC', false, NULL, false, NULL, 'Q = CV = 150 × 10⁻⁶ × 330 = 0.0495 C. In mC: 0.04950 × 1000 = 49.5. Mark scheme (3 marks). C1: Q = CV. C1: unit conversion. A1: Q = 49.5 mC.', 3),
('18428588-db2c-55f6-bda8-e344749d2f9a', '34322ed1-8148-406d-97ee-947a4eca6b7f', '98bbfcc1-1e3c-5d99-be0d-e19121542f69', 'a-level', '23.1', '9702 coursebook 23.1 · Capacitors and capacitance', 25, 25, 'A 100 µF capacitor is charged to 9.0 V. Calculate the number of electrons that have been moved from one plate to the other. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '5.625e15', NULL, false, NULL, false, NULL, 'Q = CV = 100 × 10⁻⁶ × 9.0 = 9.0 × 10⁻⁴ C. N = Q/e = 9.0 × 10⁻⁴ ÷ 1.60 × 10⁻¹⁹ = 5.62 × 10¹⁵. Mark scheme (4 marks). C1: Q = CV. C1: N = Q/e. B1: charge moved = charge on one plate. A1: N = 5.63 × 10¹⁵.', 4),
('ea38a1d1-252a-5933-994d-c016fd551043', '34322ed1-8148-406d-97ee-947a4eca6b7f', '98bbfcc1-1e3c-5d99-be0d-e19121542f69', 'a-level', '23.1', '9702 coursebook 23.1 · Capacitors and capacitance', 26, 26, 'For a parallel-plate capacitor, C = ε₀A/d. It stays connected to a battery while its plate separation is doubled. Which row is correct?', NULL, 2, 'multiple_choice'::answer_type, 'C halves and Q halves', NULL, false, NULL, false, NULL, 'C ∝ 1/d; V is fixed by the battery, so Q = CV halves too. Mark scheme (3 marks). C1: C ∝ 1/d. C1: V fixed, so Q ∝ C. A1: C (C halves and Q halves).', 3),
('33fff9e9-8ad1-5113-88dc-e70a73bc2fdf', '34322ed1-8148-406d-97ee-947a4eca6b7f', '98bbfcc1-1e3c-5d99-be0d-e19121542f69', 'a-level', '23.1', '9702 coursebook 23.1 · Capacitors and capacitance', 27, 27, 'A parallel-plate capacitor has plates of area 0.040 m² separated by 1.0 mm of air. Using C = ε₀A/d, calculate its capacitance in pF. Take ε₀ = 8.85 × 10⁻¹² F m⁻¹.', NULL, 2, 'numeric'::answer_type, '354', 'pF', false, NULL, false, NULL, 'C = ε₀A/d = 8.85 × 10⁻¹² × 0.040 ÷ 1.0 × 10⁻³ = 3.54 × 10⁻¹⁰ F. In pF: 3.540 × 10⁻¹⁰ × 10¹² = 354. Mark scheme (3 marks). C1: C = ε₀A/d with d in m. C1: conversion to pF. A1: C = 354 pF.', 3),
('50ec7774-88de-5694-bb41-0d5366b5fc6e', '34322ed1-8148-406d-97ee-947a4eca6b7f', '98bbfcc1-1e3c-5d99-be0d-e19121542f69', 'a-level', '23.1', '9702 coursebook 23.1 · Capacitors and capacitance', 28, 28, 'The capacitance of an isolated conducting sphere of radius r is C = 4πε₀r. Calculate the capacitance of a sphere of radius 0.15 m, in pF. Take ε₀ = 8.85 × 10⁻¹² F m⁻¹.', NULL, 2, 'numeric'::answer_type, '16.68', 'pF', false, NULL, false, NULL, 'C = 4πε₀r = 4 × π × 8.85 × 10⁻¹² × 0.15 = 1.67 × 10⁻¹¹ F. In pF: 1.668 × 10⁻¹¹ × 10¹² = 16.7. Mark scheme (3 marks). C1: C = 4πε₀r. C1: conversion to pF. A1: C = 16.7 pF.', 3),
('19b57acf-37de-56ab-97d6-e997cb0da0f0', '34322ed1-8148-406d-97ee-947a4eca6b7f', '98bbfcc1-1e3c-5d99-be0d-e19121542f69', 'a-level', '23.1', '9702 coursebook 23.1 · Capacitors and capacitance', 29, 29, 'A capacitor is charged through a resistor from a battery. Why does the charging current decrease with time?', NULL, 2, 'multiple_choice'::answer_type, 'As the capacitor''s p.d. rises, the p.d. across the resistor falls, so the current falls', NULL, false, NULL, false, NULL, 'I = (E − V_C)/R; V_C rises towards E. Mark scheme (3 marks). C1: V_C rises. C1: p.d. across R = E − V_C falls. A1: A (As the capacitor''s p.d. rises, the p.d. across the resistor falls, so the current falls).', 3),
('2e5c2db7-8c58-52dd-82b0-fedb46472833', '34322ed1-8148-406d-97ee-947a4eca6b7f', '98bbfcc1-1e3c-5d99-be0d-e19121542f69', 'a-level', '23.1', '9702 coursebook 23.1 · Capacitors and capacitance', 30, 30, 'The dome of a Van de Graaff generator has a capacitance of 20 pF. Calculate the charge on it when its potential is 200 kV, in µC.', NULL, 2, 'numeric'::answer_type, '4 uC', 'µC', false, NULL, false, NULL, 'Q = CV = 20 × 10⁻¹² × 200 × 10³ = 4.0 × 10⁻⁶ C. In µC: 4.0 × 10⁻⁶ × 10⁶ = 4.0. Mark scheme (3 marks). C1: Q = CV. C1: prefixes converted. A1: Q = 4.0 µC.', 3),
('0ed51387-4b94-5c4e-96fc-e1bc9cc301cf', '34322ed1-8148-406d-97ee-947a4eca6b7f', '98bbfcc1-1e3c-5d99-be0d-e19121542f69', 'a-level', '23.1', '9702 coursebook 23.1 · Capacitors and capacitance', 31, 31, 'What does a charged capacitor actually store?', NULL, 2, 'multiple_choice'::answer_type, 'Energy, with equal and opposite charges separated on its plates', NULL, false, NULL, false, NULL, 'The total charge is zero; the separation of charge stores energy in the electric field. Mark scheme (3 marks). C1: net charge zero. C1: energy stored in field. A1: D (Energy, with equal and opposite charges separated on its plates).', 3),
('e3d79566-15d7-569e-b263-2da29aa70dd4', '34322ed1-8148-406d-97ee-947a4eca6b7f', '98bbfcc1-1e3c-5d99-be0d-e19121542f69', 'a-level', '23.1', '9702 coursebook 23.1 · Capacitors and capacitance', 32, 32, 'A 470 µF capacitor is charged from zero by a constant current of 20 µA. Calculate the time taken for the p.d. across it to reach 6.0 V.', NULL, 2, 'numeric'::answer_type, '141', 's', false, NULL, false, NULL, 'Q = CV = 470 × 10⁻⁶ × 6.0 = 0.00282 C. t = Q/I = 0.00282 ÷ 20 × 10⁻⁶ = 141 s. Mark scheme (4 marks). C1: Q = CV. C1: Q = It. C1: rearranged for t. A1: t = 141 s.', 4),
('caefd43c-431a-5bfb-89dd-752950088c2d', '34322ed1-8148-406d-97ee-947a4eca6b7f', '98bbfcc1-1e3c-5d99-be0d-e19121542f69', 'a-level', '23.1', '9702 coursebook 23.1 · Capacitors and capacitance', 33, 33, 'A charged capacitor is disconnected from its battery. A sheet of dielectric is then slid between its plates, increasing the capacitance. Which row is correct?', NULL, 2, 'multiple_choice'::answer_type, 'Q unchanged, V decreases', NULL, false, NULL, false, NULL, 'Isolated plates keep their charge; V = Q/C falls as C rises. Mark scheme (4 marks). C1: isolated, so Q constant. C1: V = Q/C. C1: C up so V down. A1: B (Q unchanged, V decreases).', 4),
('c0775f1a-349c-5541-a541-48b3ebd4fe86', '34322ed1-8148-406d-97ee-947a4eca6b7f', '98bbfcc1-1e3c-5d99-be0d-e19121542f69', 'a-level', '23.1', '9702 coursebook 23.1 · Capacitors and capacitance', 34, 34, 'While a capacitor charges, the current falls steadily from 3.0 mA to zero in 4.0 s, and the final p.d. is 6.0 V. Calculate the capacitance in µF.', NULL, 2, 'numeric'::answer_type, '1000', 'µF', false, NULL, false, ARRAY['0.001']::text[], 'Q = area under I–t graph = 0.5 × 3.0 × 10⁻³ × 4.0 = 6.0 × 10⁻³ C. C = 6.0 × 10⁻³ ÷ 6.0 = 1.0 × 10⁻³ F. In µF: 1.0 × 10⁻³ × 10⁶ = 1000. Mark scheme (3 marks). C1: Q = area of triangle. C1: C = Q/V. A1: C = 1000 µF.', 3),
('d7e80c70-148b-5f3b-a504-f7ae71d69998', '34322ed1-8148-406d-97ee-947a4eca6b7f', '98bbfcc1-1e3c-5d99-be0d-e19121542f69', 'a-level', '23.1', '9702 coursebook 23.1 · Capacitors and capacitance', 35, 35, 'A 10 F supercapacitor is charged to 2.7 V. For how long could it supply a steady current of 50 mA if all its charge were used?', NULL, 2, 'numeric'::answer_type, '540', 's', false, NULL, false, NULL, 'Q = CV = 10 × 2.7 = 27 C. t = Q/I = 27 ÷ 50 × 10⁻³ = 540 s. Mark scheme (3 marks). C1: Q = CV. C1: t = Q/I. A1: t = 540 s.', 3),
('2501dd55-3b4a-5276-99b0-ce12af35eaae', '34322ed1-8148-406d-97ee-947a4eca6b7f', '98bbfcc1-1e3c-5d99-be0d-e19121542f69', 'a-level', '23.1', '9702 coursebook 23.1 · Capacitors and capacitance', 36, 36, 'A capacitor is connected through a resistor to a 6.0 V battery and left for a long time. Which describes the final state?', NULL, 2, 'multiple_choice'::answer_type, 'The p.d. across the capacitor is 6.0 V and the current is zero', NULL, false, NULL, false, NULL, 'Charging stops when V_C equals the e.m.f., because there is then no p.d. across the resistor. Mark scheme (3 marks). C1: V_C = e.m.f. C1: I = 0. A1: C (The p.d. across the capacitor is 6.0 V and the current is zero).', 3),
('e8e3bb4f-2ac1-503c-a4f6-204e651fb40f', '34322ed1-8148-406d-97ee-947a4eca6b7f', '98bbfcc1-1e3c-5d99-be0d-e19121542f69', 'a-level', '23.1', '9702 coursebook 23.1 · Capacitors and capacitance', 37, 37, 'A capacitor has plates of area 0.020 m² separated by a 0.50 mm sheet of dielectric with relative permittivity 4.0. Using C = ε₀εᵣA/d, calculate the capacitance in nF. Take ε₀ = 8.85 × 10⁻¹² F m⁻¹.', NULL, 2, 'numeric'::answer_type, '1.416', 'nF', false, NULL, false, ARRAY['1.416e-9']::text[], 'C = 4.0 × 8.85 × 10⁻¹² × 0.020 ÷ 0.50 × 10⁻³ = 1.42 × 10⁻⁹ F. In nF: 1.416 × 10⁻⁹ × 10⁹ = 1.42. Mark scheme (3 marks). C1: C = ε₀εᵣA/d. C1: conversion to nF. A1: C = 1.42 nF.', 3),
('2b2090ff-b957-5e1c-885d-1ac97ee116ca', '34322ed1-8148-406d-97ee-947a4eca6b7f', '98bbfcc1-1e3c-5d99-be0d-e19121542f69', 'a-level', '23.1', '9702 coursebook 23.1 · Capacitors and capacitance', 38, 38, 'Calculate the extra charge that must flow onto a 220 µF capacitor to raise the p.d. across it from 4.0 V to 10 V. Give your answer in mC.', NULL, 2, 'numeric'::answer_type, '1.32 mC', 'mC', false, NULL, false, NULL, 'ΔQ = CΔV = 220 × 10⁻⁶ × (10 − 4.0) = 0.00132 C. In mC: 0.00132 × 1000 = 1.32. Mark scheme (4 marks). M1: ΔQ = CΔV. C1: ΔV = 6.0 V. C1: substitution. A1: ΔQ = 1.32 mC.', 4),
('836ac6f5-5520-5c14-b4ea-087b1478c48d', '34322ed1-8148-406d-97ee-947a4eca6b7f', '98bbfcc1-1e3c-5d99-be0d-e19121542f69', 'a-level', '23.1', '9702 coursebook 23.1 · Capacitors and capacitance', 39, 39, 'Why are most practical capacitances given in µF, nF or pF rather than F?', NULL, 2, 'multiple_choice'::answer_type, 'One farad is a very large capacitance: a parallel-plate capacitor of 1 F with a 1 mm air gap would need plates of about 10⁸ m²', NULL, false, NULL, false, NULL, 'From C = ε₀A/d, A = Cd/ε₀ ≈ 1 × 10⁻³ ÷ 8.85 × 10⁻¹² ≈ 1 × 10⁸ m². Mark scheme (3 marks). C1: 1 F is very large. C1: estimate of plate area. A1: A (One farad is a very large capacitance: a parallel-plate capacitor of 1 F with a 1 mm air gap would need plates of about 10⁸ m²).', 3),
('1b6bcd96-74dd-53a7-833b-bc932c742677', '34322ed1-8148-406d-97ee-947a4eca6b7f', '98bbfcc1-1e3c-5d99-be0d-e19121542f69', 'a-level', '23.1', '9702 coursebook 23.1 · Capacitors and capacitance', 40, 40, 'A capacitor is charged by a constant current of 0.10 mA. The p.d. across it is recorded: t/s = 0, 10, 20, 30, 40 and V/V = 0, 2.1, 4.3, 6.4, 8.5. (a) Explain how the data show that the current is constant. (b) Calculate the gradient of the V–t graph. (c) Use the gradient to calculate the capacitance, in µF. (d) Suggest how the constant current could be maintained in practice. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '470.6', 'µF', false, NULL, false, ARRAY['4.706e-4']::text[], '(a) V rises by about 2.1 V every 10 s: a straight line through the origin, so charge is added at a steady rate. (b) Gradient = 8.5 ÷ 40 = 0.212 V s⁻¹. (c) Q = CV and Q = It, so I = C × gradient: C = 0.10 × 10⁻³ ÷ 0.2125 = 4.71 × 10⁻⁴ F. In µF: 4.706 × 10⁻⁴ × 10⁶ = 471. (d) Reduce a variable resistor gradually to keep the ammeter reading steady. Mark scheme (6 marks). B1: linear V–t means constant rate of charging. C1: gradient. M1: I = C dV/dt. C1: substitution. B1: adjust a variable resistor. A1: C = 471 µF.', 6),
('119096db-8dcd-587b-ab19-7a114318b567', '34322ed1-8148-406d-97ee-947a4eca6b7f', '98bbfcc1-1e3c-5d99-be0d-e19121542f69', 'a-level', '23.1', '9702 coursebook 23.1 · Capacitors and capacitance', 41, 41, 'A parallel-plate air capacitor has plates of area 0.25 m² separated by 2.0 mm, so that C = ε₀A/d. (a) Calculate its capacitance in nF. (b) It is connected to a 500 V supply. Calculate the charge stored. (c) Calculate the electric field strength between the plates. Give only the answer to (a). Take ε₀ = 8.85 × 10⁻¹² F m⁻¹.', NULL, 3, 'numeric'::answer_type, '1.106', 'nF', false, NULL, false, ARRAY['1.106e-9']::text[], '(a) C = 8.85 × 10⁻¹² × 0.25 ÷ 2.0 × 10⁻³ = 1.11 × 10⁻⁹ F. In nF: 1.106 × 10⁻⁹ × 10⁹ = 1.11. (b) Q = CV = 1.106 × 10⁻⁹ × 500 = 5.53 × 10⁻⁷ C. (c) E = V/d = 500 ÷ 2.0 × 10⁻³ = 2.5 × 10⁵ V m⁻¹. Mark scheme (5 marks). C1: C = ε₀A/d. C1: conversion to nF. C1: Q = CV. C1: E = V/d. A1: C = 1.11 nF.', 5),
('39b65385-b1e9-5f6f-97f3-a4a554f65018', '34322ed1-8148-406d-97ee-947a4eca6b7f', '98bbfcc1-1e3c-5d99-be0d-e19121542f69', 'a-level', '23.1', '9702 coursebook 23.1 · Capacitors and capacitance', 42, 42, 'A thundercloud and the ground can be modelled as a parallel-plate capacitor. The cloud base has an area of 1.0 × 10⁷ m² and is 1.0 km above the ground. (a) Using C = ε₀A/d, calculate the capacitance. (b) The cloud base carries a charge of 20 C. Calculate the p.d. between cloud and ground. (c) Calculate the average field strength and compare it with the breakdown field of air, 3.0 × 10⁶ V m⁻¹. Give only the answer to (b). Take ε₀ = 8.85 × 10⁻¹² F m⁻¹.', NULL, 3, 'numeric'::answer_type, '2.26e8', 'V', false, NULL, false, NULL, '(a) C = 8.85 × 10⁻¹² × 1.0 × 10⁷ ÷ 1000 = 8.85 × 10⁻⁸ F. (b) V = Q/C = 20 ÷ 8.850 × 10⁻⁸ = 2.26 × 10⁸ V. (c) E = 2.260 × 10⁸ ÷ 1000 = 2.26 × 10⁵ V m⁻¹, about a tenth of the breakdown value, so breakdown must start where the field is locally stronger. Mark scheme (6 marks). C1: C = ε₀A/d. A1: C value. C1: V = Q/C. C1: E = V/d. B1: comparison with breakdown field. A1: V = 2.26 × 10⁸ V.', 6),
('5058629d-ce94-524d-b694-48286ca22918', '34322ed1-8148-406d-97ee-947a4eca6b7f', '98bbfcc1-1e3c-5d99-be0d-e19121542f69', 'a-level', '23.1', '9702 coursebook 23.1 · Capacitors and capacitance', 43, 43, 'A student uses a coulombmeter to measure the charge on a capacitor at different p.d.s: V/V = 2.0, 4.0, 6.0, 8.0 and Q/µC = 0.94, 1.90, 2.80, 3.78. (a) Describe the relationship shown. (b) Calculate the gradient of the Q–V graph using the first and last points. (c) State the capacitance in µF. (d) Suggest why the line may not pass exactly through the origin. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '0.4733', 'µF', false, NULL, false, ARRAY['4.733e-7']::text[], '(a) Q is proportional to V. (b) Gradient = (3.78 − 0.94) ÷ (8.0 − 2.0) = 0.473 µC V⁻¹. (c) C = gradient = 0.473 µF. (d) Charge leaks from the capacitor or the meter before the reading is taken, or the meter has a zero error. Mark scheme (5 marks). B1: Q ∝ V. C1: gradient. M1: C = gradient. B1: leakage or zero error. A1: C = 0.473 µF.', 5),
('96ce828f-5726-5e35-8d12-a3c200c2c515', '34322ed1-8148-406d-97ee-947a4eca6b7f', '98bbfcc1-1e3c-5d99-be0d-e19121542f69', 'a-level', '23.1', '9702 coursebook 23.1 · Capacitors and capacitance', 44, 44, 'An isolated metal sphere of radius 0.10 m in air has capacitance C = 4πε₀r. The field at its surface is V/r, and air breaks down at 3.0 × 10⁶ V m⁻¹. (a) Calculate the capacitance in pF. (b) Calculate the largest potential the sphere can reach. (c) Calculate the largest charge it can hold, in µC. Give only the answer to (c). Take ε₀ = 8.85 × 10⁻¹² F m⁻¹.', NULL, 3, 'numeric'::answer_type, '3.336 uC', 'µC', false, NULL, false, NULL, '(a) C = 4 × π × 8.85 × 10⁻¹² × 0.10 = 1.11 × 10⁻¹¹ F. In pF: 1.112 × 10⁻¹¹ × 10¹² = 11.1. (b) V = Er = 3.0 × 10⁶ × 0.10 = 3.0 × 10⁵ V. (c) Q = CV = 1.112 × 10⁻¹¹ × 3.0 × 10⁵ = 3.34 × 10⁻⁶ C. In µC: 3.336 × 10⁻⁶ × 10⁶ = 3.34. Mark scheme (6 marks). C1: C = 4πε₀r. C1: V = Er. C1: Q = CV. C1: conversion to µC. M1: maximum set by breakdown field. A1: Q = 3.34 µC.', 6),
('39ac4616-aab8-55bf-92a4-90de3716cd41', '34322ed1-8148-406d-97ee-947a4eca6b7f', '98bbfcc1-1e3c-5d99-be0d-e19121542f69', 'a-level', '23.1', '9702 coursebook 23.1 · Capacitors and capacitance', 45, 45, 'A bank of supercapacitors with total capacitance 3000 F is charged to 2.7 V. (a) Calculate the charge stored. (b) Calculate the number of electrons moved during charging. (c) The bank is discharged to 1.35 V in 60 s. Calculate the average current. Give only the answer to (c). Take e = 1.60 × 10⁻¹⁹ C.', NULL, 3, 'numeric'::answer_type, '67.5', 'A', false, NULL, false, NULL, '(a) Q = CV = 3000 × 2.7 = 8100 C. (b) N = 8100 ÷ 1.60 × 10⁻¹⁹ = 5.06 × 10²². (c) ΔQ = 3000 × (2.7 − 1.35) = 4050 C, so I = 4050 ÷ 60 = 67.5 A. Mark scheme (5 marks). C1: Q = CV. C1: N = Q/e. M1: ΔQ = CΔV. C1: I = ΔQ/t. A1: I = 67.5 A.', 5),
('8e99dd18-01ff-5b69-90b5-af104c9850cb', '34322ed1-8148-406d-97ee-947a4eca6b7f', '98bbfcc1-1e3c-5d99-be0d-e19121542f69', 'a-level', '23.1', '9702 coursebook 23.1 · Capacitors and capacitance', 46, 46, 'An air-filled capacitor of 200 pF stays connected to a 50 V supply while a slab of dielectric of relative permittivity 3.0 is inserted, filling the gap. (a) Calculate the charge before the slab is inserted. (b) Calculate the new capacitance. (c) Calculate the extra charge that flows from the supply, in nC. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '20 nC', 'nC', false, NULL, false, NULL, '(a) Q₁ = 200 × 10⁻¹² × 50 = 1.0 × 10⁻⁸ C. (b) C₂ = 3.0 × 200 = 600 pF. (c) Q₂ = 600 × 10⁻¹² × 50 = 3.0 × 10⁻⁸ C. ΔQ = 3.0 × 10⁻⁸ − 1.0 × 10⁻⁸ = 2.0 × 10⁻⁸ C. In nC: 2.0 × 10⁻⁸ × 10⁹ = 20. Mark scheme (5 marks). C1: Q = CV. C1: C × εᵣ. M1: V fixed by supply. C1: ΔQ. A1: ΔQ = 20 nC.', 5),
('3f756bbc-56fc-579d-90e1-355f62a87ddd', '34322ed1-8148-406d-97ee-947a4eca6b7f', '98bbfcc1-1e3c-5d99-be0d-e19121542f69', 'a-level', '23.1', '9702 coursebook 23.1 · Capacitors and capacitance', 47, 47, 'A 60 pF parallel-plate capacitor is charged to 120 V and then disconnected from the supply. Its plate separation is then increased to four times its original value (C = ε₀A/d). (a) Calculate the charge on the capacitor. (b) Calculate the new capacitance. (c) Calculate the new p.d. between the plates. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '480', 'V', false, NULL, false, NULL, '(a) Q = CV = 60 × 10⁻¹² × 120 = 7.2 × 10⁻⁹ C. (b) C ∝ 1/d, so C = 60 ÷ 4 = 15 pF. (c) Q is unchanged because the plates are isolated: V = Q/C = 7.2 × 10⁻⁹ ÷ 15 × 10⁻¹² = 480 V. Mark scheme (5 marks). C1: Q = CV. C1: C ∝ 1/d. M1: Q constant when isolated. C1: V = Q/C. A1: V = 480 V.', 5),
('81211b0e-9078-5d99-84b4-702f6b1d37bf', '34322ed1-8148-406d-97ee-947a4eca6b7f', '98bbfcc1-1e3c-5d99-be0d-e19121542f69', 'a-level', '23.1', '9702 coursebook 23.1 · Capacitors and capacitance', 48, 48, 'A capacitor is charged from a 9.0 V supply through a resistor. The current is recorded: t/s = 0, 10, 20, 30 and I/mA = 2.0, 1.2, 0.72, 0.43. At t = 30 s the p.d. across the capacitor is 7.05 V. (a) Use the trapezium rule to estimate the charge that flowed in the first 30 s, in mC. (b) Use your answer to estimate the capacitance, in µF. (c) Explain whether your estimate of the charge is too high or too low. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '4447', 'µF', false, NULL, false, ARRAY['0.004447']::text[], '(a) Q ≈ 10 × (2.0 + 1.2) ÷ 2 + 10 × (1.2 + 0.72) ÷ 2 + 10 × (0.72 + 0.43) ÷ 2 = 31.3 mC. (b) C = Q/V = 31.35 × 10⁻³ ÷ 7.05 = 0.00445 F. In µF: 0.004447 × 10⁶ = 4450. (c) Too high: the curve bends below the straight lines joining the points, so the trapezia include extra area. Mark scheme (6 marks). C1: area under I–t graph = charge. C1: trapezium rule applied. M1: C = Q/V. C1: conversion to µF. B1: overestimate, curve below chords. A1: C = 4450 µF.', 6),
('60665d90-ea8a-54ab-9e32-fa4279585fe6', '34322ed1-8148-406d-97ee-947a4eca6b7f', '98bbfcc1-1e3c-5d99-be0d-e19121542f69', 'a-level', '23.1', '9702 coursebook 23.1 · Capacitors and capacitance', 49, 49, 'A 2.0 µF capacitor is charged to 12 V. (a) Calculate the charge on each plate. (b) Calculate the number of electrons that moved through the circuit from one plate to the other. (c) Explain why the total charge on the capacitor is zero, even though it is "charged". Give only the answer to (b). Take e = 1.60 × 10⁻¹⁹ C.', NULL, 3, 'numeric'::answer_type, '1.5e14', NULL, false, NULL, false, NULL, '(a) Q = CV = 2.0 × 10⁻⁶ × 12 = 2.4 × 10⁻⁵ C, +2.4 × 10⁻⁵ C on one plate and −2.4 × 10⁻⁵ C on the other. (b) N = 2.4 × 10⁻⁵ ÷ 1.60 × 10⁻¹⁹ = 1.50 × 10¹⁴. (c) Every electron added to one plate came from the other, so the charges are equal and opposite and sum to zero. Mark scheme (5 marks). C1: Q = CV. C1: N = Q/e. B1: equal and opposite charges. B1: electrons moved, not created. A1: N = 1.50 × 10¹⁴.', 5),
('70a5fabb-5242-587d-a082-dd31c31de61a', '34322ed1-8148-406d-97ee-947a4eca6b7f', '98bbfcc1-1e3c-5d99-be0d-e19121542f69', 'a-level', '23.1', '9702 coursebook 23.1 · Capacitors and capacitance', 50, 50, 'In a condenser microphone, the diaphragm and a fixed back-plate form a parallel-plate capacitor (C = ε₀A/d) of area 1.0 × 10⁻⁴ m² and separation 20 µm, held at 50 V. A sound wave pushes the diaphragm so that the separation becomes 19 µm. (a) Calculate the capacitance at 20 µm. (b) Calculate the capacitance at 19 µm. (c) Calculate the charge that flows onto the capacitor, in pC. (d) Explain how this produces an electrical signal. Give only the answer to (c). Take ε₀ = 8.85 × 10⁻¹² F m⁻¹.', NULL, 3, 'numeric'::answer_type, '116.4', 'pC', false, NULL, false, NULL, '(a) C₁ = 8.85 × 10⁻¹² × 1.0 × 10⁻⁴ ÷ 20 × 10⁻⁶ = 4.43 × 10⁻¹¹ F. (b) C₂ = 8.85 × 10⁻¹² × 1.0 × 10⁻⁴ ÷ 19 × 10⁻⁶ = 4.66 × 10⁻¹¹ F. (c) ΔQ = VΔC = 50 × (4.658 × 10⁻¹¹ − 4.425 × 10⁻¹¹) = 1.16 × 10⁻¹⁰ C. In pC: 1.164 × 10⁻¹⁰ × 10¹² = 116. (d) As the diaphragm vibrates, charge flows on and off the plates; this current through a resistor gives a p.d. that follows the sound. Mark scheme (6 marks). C1: C at 20 µm. C1: C at 19 µm. M1: ΔQ = VΔC. C1: conversion to pC. B1: changing charge gives current signal. A1: ΔQ = 116 pC.', 6)
