('4ef7160a-99f6-5368-a872-49c6e55bb5b0', '7d96b0f3-15b5-5b7a-8dee-d29ae5633276', '−Q', 'D', true, 3),
('51513301-f560-586c-8ed2-4016aa3c99ef', '8f1401ff-24e2-50f9-a3f9-c67250d003a2', 'A curve through the origin', 'A', false, 0),
('2e0b08a0-07a8-58aa-b8c8-b7331b919f03', '8f1401ff-24e2-50f9-a3f9-c67250d003a2', 'A straight line through the origin, whose gradient is the capacitance', 'B', true, 1),
