('a027eb71-2bd5-5538-9b6f-8b5b8ff4b5d1', 'e5c5b3ae-5899-524e-844f-c208963b459a', 'Electrons jump across the gap between the plates', 'A', false, 0),
('6ea03354-a4e9-5927-90e6-a52b2cc426b8', 'e5c5b3ae-5899-524e-844f-c208963b459a', 'Protons flow onto the positive plate', 'B', false, 1),
('c5bcc2e3-6475-5352-8509-3bfc4cefdd9f', 'e5c5b3ae-5899-524e-844f-c208963b459a', 'Electrons flow round the circuit from one plate to the other; none cross the insulating gap', 'C', true, 2),
('839b6231-8b0d-54cc-a820-1f3814703a2a', 'e5c5b3ae-5899-524e-844f-c208963b459a', 'No current flows at any time', 'D', false, 3),
