('28df27ac-90d8-5815-b130-e499711dc5da', '0d441f8a-409c-5dfb-afa8-ea80439fb676', 'The energy stored', 'A', false, 0),
('0abbc6f2-8ffc-55ce-89cd-f0928bf294c8', '0d441f8a-409c-5dfb-afa8-ea80439fb676', 'The charge stored on the capacitor', 'B', true, 1),
('f1c7543d-41dd-5226-a487-aaa88f9d4a1f', '0d441f8a-409c-5dfb-afa8-ea80439fb676', 'The capacitance', 'C', false, 2),
