('72b52938-1944-597e-ad91-c19ba33368b8', '0ed51387-4b94-5c4e-96fc-e1bc9cc301cf', 'A net charge, so the whole capacitor is charged', 'A', false, 0),
('a5f2f2d1-c331-5ae9-a438-55577c583d61', '0ed51387-4b94-5c4e-96fc-e1bc9cc301cf', 'Electric current', 'B', false, 1),
('93d6b3e3-3be3-5d9b-abcc-32727c2e97b9', '0ed51387-4b94-5c4e-96fc-e1bc9cc301cf', 'Only positive charge', 'C', false, 2),
('8938fc40-7ddf-5054-84b1-ea9c54a1688e', '0ed51387-4b94-5c4e-96fc-e1bc9cc301cf', 'Energy, with equal and opposite charges separated on its plates', 'D', true, 3),
('5dd0a2d3-9d0d-54d2-9b46-b5e420a7023a', 'caefd43c-431a-5bfb-89dd-752950088c2d', 'Q increases, V unchanged', 'A', false, 0),
('6a78af0f-69e7-5e79-aa02-4b1bc98fa2db', 'caefd43c-431a-5bfb-89dd-752950088c2d', 'Q unchanged, V decreases', 'B', true, 1),
('d0ce3126-1bb7-5873-aa31-ea3e5608e493', 'caefd43c-431a-5bfb-89dd-752950088c2d', 'Q unchanged, V increases', 'C', false, 2),
('a63da64b-f1bc-5851-868f-adf2fa7c3bf0', 'caefd43c-431a-5bfb-89dd-752950088c2d', 'Q decreases, V decreases', 'D', false, 3),
('2d47d994-9048-571a-9516-2e0d9e609f19', '2501dd55-3b4a-5276-99b0-ce12af35eaae', 'The p.d. across the capacitor is 3.0 V and the current is constant', 'A', false, 0),
('40ab37c4-d9bb-5417-ab96-807941923e72', '2501dd55-3b4a-5276-99b0-ce12af35eaae', 'The current is a maximum and the p.d. is zero', 'B', false, 1),
('02ba888b-4554-53b4-8467-3ad03013abef', '2501dd55-3b4a-5276-99b0-ce12af35eaae', 'The p.d. across the capacitor is 6.0 V and the current is zero', 'C', true, 2),
('9be61c95-2858-52e7-8aa5-78c040c39a84', '2501dd55-3b4a-5276-99b0-ce12af35eaae', 'Charge keeps flowing across the gap', 'D', false, 3),
('d8650476-79d0-52a4-ae71-77b726463d78', '836ac6f5-5520-5c14-b4ea-087b1478c48d', 'One farad is a very large capacitance: a parallel-plate capacitor of 1 F with a 1 mm air gap would need plates of about 10⁸ m²', 'A', true, 0),
('13a47474-ca85-5498-949a-d1eecd96a5eb', '836ac6f5-5520-5c14-b4ea-087b1478c48d', 'The farad is not an SI unit', 'B', false, 1),
('87aebf5e-ca98-57e5-becd-7d48189a43a7', '836ac6f5-5520-5c14-b4ea-087b1478c48d', 'Capacitors cannot store more than 1 µC', 'C', false, 2),
('acb04e74-b64f-561d-bfe6-ea213a41798c', '836ac6f5-5520-5c14-b4ea-087b1478c48d', 'Larger units make the voltage too high', 'D', false, 3)
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points) VALUES
('cee7555b-401d-5784-a1bf-cf5b626c3f31', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1f2d9fae-c676-5618-9e77-df3b1c100686', 'a-level', '23.2', '9702 coursebook 23.2 · Energy stored in a capacitor', 9, 9, 'Which expression gives the energy W stored in a capacitor carrying charge Q at p.d. V?', NULL, 1, 'multiple_choice'::answer_type, 'W = ½QV', NULL, false, NULL, false, NULL, 'The p.d. rises from 0 to V while charge is added, so the average p.d. is V/2. Mark scheme (1 mark). B1: C (W = ½QV).', 1),
('54e92b9a-9f54-5d4e-8d9f-45e905f7ae30', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1f2d9fae-c676-5618-9e77-df3b1c100686', 'a-level', '23.2', '9702 coursebook 23.2 · Energy stored in a capacitor', 10, 10, 'A 2200 µF smoothing capacitor in a power supply is at 9.0 V. How much energy does it hold?', NULL, 1, 'numeric'::answer_type, '0.0891', 'J', false, NULL, false, NULL, 'W = ½CV² = 0.5 × 2200 × 10⁻⁶ × 9.0² = 0.0891 J. Mark scheme (2 marks). C1: W = ½CV². A1: W = 0.0891 J.', 2),
('ee8b33fd-16d2-5a84-b00d-a42a14b367f4', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1f2d9fae-c676-5618-9e77-df3b1c100686', 'a-level', '23.2', '9702 coursebook 23.2 · Energy stored in a capacitor', 11, 11, 'A defibrillator capacitor of 32 µF is charged to 5.0 kV. Calculate the energy stored.', NULL, 1, 'numeric'::answer_type, '400', 'J', false, NULL, false, NULL, 'W = ½CV² = 0.5 × 32 × 10⁻⁶ × (5.0 × 10³)² = 400 J. Mark scheme (2 marks). C1: W = ½CV² with units converted. A1: W = 400 J.', 2),
('894b373c-3dbe-5d1e-b69a-debdb83e02ab', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1f2d9fae-c676-5618-9e77-df3b1c100686', 'a-level', '23.2', '9702 coursebook 23.2 · Energy stored in a capacitor', 12, 12, 'What does the area under a graph of p.d. (y-axis) against charge (x-axis) for a capacitor represent?', NULL, 1, 'multiple_choice'::answer_type, 'The energy stored', NULL, false, NULL, false, NULL, 'W = ∫V dQ, the area under the V–Q line: a triangle of area ½QV. Mark scheme (1 mark). B1: A (The energy stored).', 1),
('688a75cd-fbca-5247-96e4-9cb8795cf90d', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1f2d9fae-c676-5618-9e77-df3b1c100686', 'a-level', '23.2', '9702 coursebook 23.2 · Energy stored in a capacitor', 13, 13, 'A camera flash capacitor holds a charge of 3.0 mC at a p.d. of 6.0 V. Calculate the energy it stores, in mJ.', NULL, 1, 'numeric'::answer_type, '9 mJ', 'mJ', false, NULL, false, NULL, 'W = ½QV = 0.5 × 3.0 × 10⁻³ × 6.0 = 9.0 × 10⁻³ J. In mJ: 9.0 × 10⁻³ × 1000 = 9.0. Mark scheme (2 marks). C1: W = ½QV. A1: W = 9.0 mJ.', 2),
('44257dd0-1cc0-50bc-b306-0459db8602f5', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1f2d9fae-c676-5618-9e77-df3b1c100686', 'a-level', '23.2', '9702 coursebook 23.2 · Energy stored in a capacitor', 14, 14, 'The p.d. across a capacitor is doubled. What happens to the energy stored?', NULL, 1, 'multiple_choice'::answer_type, 'It becomes four times as large', NULL, false, NULL, false, NULL, 'W = ½CV², so W ∝ V². Mark scheme (1 mark). B1: D (It becomes four times as large).', 1),
('785e1a3b-5cba-5fcb-be06-773c88fd5fdf', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1f2d9fae-c676-5618-9e77-df3b1c100686', 'a-level', '23.2', '9702 coursebook 23.2 · Energy stored in a capacitor', 15, 15, 'A 0.010 F capacitor carries a charge of 0.020 C. Calculate the energy stored.', NULL, 1, 'numeric'::answer_type, '0.02', 'J', false, NULL, false, NULL, 'W = Q²/2C = 0.020² ÷ (2 × 0.010) = 0.020 J. Mark scheme (2 marks). C1: W = Q²/2C. A1: W = 0.020 J.', 2),
('7fc846b3-593a-5c4e-8376-f9aa2a29d6b4', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1f2d9fae-c676-5618-9e77-df3b1c100686', 'a-level', '23.2', '9702 coursebook 23.2 · Energy stored in a capacitor', 16, 16, 'A capacitor is charged fully from a battery through a resistor. What fraction of the energy supplied by the battery ends up stored in the capacitor?', NULL, 1, 'multiple_choice'::answer_type, 'One half', NULL, false, NULL, false, NULL, 'The battery supplies QV; the capacitor stores ½QV; the rest is dissipated in the resistance. Mark scheme (1 mark). B1: B (One half).', 1),
('2f27e331-a7c0-516c-a2ff-7f778b27915e', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1f2d9fae-c676-5618-9e77-df3b1c100686', 'a-level', '23.2', '9702 coursebook 23.2 · Energy stored in a capacitor', 17, 17, 'Calculate the p.d. needed to store 1.0 J of energy in a 1000 µF capacitor.', NULL, 1, 'numeric'::answer_type, '44.72', 'V', false, NULL, false, NULL, 'V = √(2W/C) = √(2 × 1.0 ÷ 1000 × 10⁻⁶) = 44.7 V. Mark scheme (2 marks). C1: rearranged W = ½CV². A1: V = 44.7 V.', 2),
('5e52579b-acdd-549f-b826-3fb47356181a', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1f2d9fae-c676-5618-9e77-df3b1c100686', 'a-level', '23.2', '9702 coursebook 23.2 · Energy stored in a capacitor', 18, 18, 'Which graph of energy stored (y-axis) against p.d. (x-axis) is correct for a capacitor?', NULL, 1, 'multiple_choice'::answer_type, 'A curve through the origin getting steeper (a parabola)', NULL, false, NULL, false, NULL, 'W = ½CV² is a square law. Mark scheme (1 mark). B1: C (A curve through the origin getting steeper (a parabola)).', 1),
('68c37e09-dfd6-52d7-9388-cd20aafc5b9b', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1f2d9fae-c676-5618-9e77-df3b1c100686', 'a-level', '23.2', '9702 coursebook 23.2 · Energy stored in a capacitor', 19, 19, 'A 1.0 F supercapacitor is charged to 5.0 V. Calculate the energy stored.', NULL, 1, 'numeric'::answer_type, '12.5', 'J', false, NULL, false, NULL, 'W = ½CV² = 0.5 × 1.0 × 5.0² = 12.5 J. Mark scheme (2 marks). C1: W = ½CV². A1: W = 12.5 J.', 2),
('52383281-e7d0-51e0-98ec-ec8fa2b02162', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1f2d9fae-c676-5618-9e77-df3b1c100686', 'a-level', '23.2', '9702 coursebook 23.2 · Energy stored in a capacitor', 20, 20, 'Where is the energy of a charged capacitor stored?', NULL, 1, 'multiple_choice'::answer_type, 'In the electric field between the plates', NULL, false, NULL, false, NULL, 'Separating the charges creates a field between the plates; the energy is associated with that field. Mark scheme (1 mark). B1: A (In the electric field between the plates).', 1),
('bb9ab0b0-148c-5b82-985d-32fbad71265b', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1f2d9fae-c676-5618-9e77-df3b1c100686', 'a-level', '23.2', '9702 coursebook 23.2 · Energy stored in a capacitor', 21, 21, 'A capacitor stores 0.50 J when the p.d. across it is 100 V. Calculate its capacitance in µF.', NULL, 1, 'numeric'::answer_type, '100', 'µF', false, NULL, false, ARRAY['1e-4']::text[], 'C = 2W/V² = 2 × 0.50 ÷ 100² = 1.0 × 10⁻⁴ F. In µF: 1.0 × 10⁻⁴ × 10⁶ = 100. Mark scheme (2 marks). C1: C = 2W/V². A1: C = 100 µF.', 2),
('7a63f444-89b5-5486-8f9a-5d4bbf8b27a3', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1f2d9fae-c676-5618-9e77-df3b1c100686', 'a-level', '23.2', '9702 coursebook 23.2 · Energy stored in a capacitor', 22, 22, 'The charge on a capacitor is halved while its capacitance stays the same. What happens to the energy stored?', NULL, 1, 'multiple_choice'::answer_type, 'It becomes one quarter of its original value', NULL, false, NULL, false, NULL, 'W = Q²/2C, so W ∝ Q². Mark scheme (1 mark). B1: D (It becomes one quarter of its original value).', 1),
('b10f0b01-70b5-513a-a307-8212af255812', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1f2d9fae-c676-5618-9e77-df3b1c100686', 'a-level', '23.2', '9702 coursebook 23.2 · Energy stored in a capacitor', 23, 23, 'How much energy is held by a 1.0 µF capacitor whose plates have a p.d. of 100 V between them?', NULL, 1, 'numeric'::answer_type, '0.005', 'J', false, NULL, false, NULL, 'W = ½CV² = 0.5 × 1.0 × 10⁻⁶ × 100² = 0.0050 J. Mark scheme (1 mark). A1: W = 0.0050 J.', 1),
('8a0e19be-8ca3-569d-b544-a382334b1b9c', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1f2d9fae-c676-5618-9e77-df3b1c100686', 'a-level', '23.2', '9702 coursebook 23.2 · Energy stored in a capacitor', 24, 24, 'A camera flash tube receives 0.80 J from its capacitor in 1.0 ms. Calculate the average power of the flash.', NULL, 1, 'numeric'::answer_type, '800', 'W', false, NULL, false, NULL, 'P = W/t = 0.80 ÷ 1.0 × 10⁻³ = 800 W. Mark scheme (2 marks). C1: P = W/t. A1: P = 800 W.', 2),
('2dc3f2be-d415-57f1-8add-fc2178298922', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1f2d9fae-c676-5618-9e77-df3b1c100686', 'a-level', '23.2', '9702 coursebook 23.2 · Energy stored in a capacitor', 25, 25, 'Compared with a rechargeable battery of similar size, what is the main advantage of a capacitor as an energy store?', NULL, 1, 'multiple_choice'::answer_type, 'It can release its energy very quickly', NULL, false, NULL, false, NULL, 'Capacitors deliver high power for a short time; batteries store more energy at a steadier p.d. Mark scheme (1 mark). B1: B (It can release its energy very quickly).', 1),
('2e1c3974-66a0-519c-9e64-9828cbc10c01', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1f2d9fae-c676-5618-9e77-df3b1c100686', 'a-level', '23.2', '9702 coursebook 23.2 · Energy stored in a capacitor', 26, 26, 'A 470 µF capacitor is charged from 6.0 V to 12 V. Calculate the increase in the energy stored.', NULL, 2, 'numeric'::answer_type, '0.02538', 'J', false, NULL, false, NULL, 'ΔW = ½C(V₂² − V₁²) = 0.5 × 470 × 10⁻⁶ × (12² − 6.0²) = 0.0254 J. Mark scheme (3 marks). M1: difference of ½CV² values. C1: substitution. A1: ΔW = 0.0254 J.', 3),
('9b186322-da26-5fb9-983b-8957d65a2898', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1f2d9fae-c676-5618-9e77-df3b1c100686', 'a-level', '23.2', '9702 coursebook 23.2 · Energy stored in a capacitor', 27, 27, 'A defibrillator must deliver 200 J from a 40 µF capacitor. Calculate the p.d. to which the capacitor must be charged, in kV.', NULL, 2, 'numeric'::answer_type, '3.162 kV', 'kV', false, NULL, false, NULL, 'V = √(2W/C) = √(2 × 200 ÷ 40 × 10⁻⁶) = 3160 V. In kV: 3162 ÷ 1000 = 3.16. Mark scheme (3 marks). C1: V = √(2W/C). C1: conversion to kV. A1: V = 3.16 kV.', 3),
('d7a8eb5e-f378-5725-a002-2c38ff5fe618', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1f2d9fae-c676-5618-9e77-df3b1c100686', 'a-level', '23.2', '9702 coursebook 23.2 · Energy stored in a capacitor', 28, 28, 'A 100 µF capacitor is charged to 12 V by a battery through a resistor. Calculate the energy dissipated in the resistor, in mJ.', NULL, 2, 'numeric'::answer_type, '7.2 mJ', 'mJ', false, NULL, false, NULL, 'Charge moved Q = CV = 100 × 10⁻⁶ × 12 = 1.2 × 10⁻³ C. Energy from battery = QV = 1.2 × 10⁻³ × 12 = 0.0144 J. Energy stored = ½QV = 0.5 × 1.2 × 10⁻³ × 12 = 0.0072 J. Dissipated = 0.0144 − 0.0072 = 0.0072 J. In mJ: 0.0072 × 1000 = 7.2. Mark scheme (4 marks). C1: battery supplies QV. C1: stored ½QV. M1: difference dissipated. A1: W = 7.2 mJ.', 4),
('01b5f306-f721-5700-9495-15b66af936cd', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1f2d9fae-c676-5618-9e77-df3b1c100686', 'a-level', '23.2', '9702 coursebook 23.2 · Energy stored in a capacitor', 29, 29, 'A graph of p.d. against charge for a capacitor is a straight line from the origin to 8.0 V at 4.0 mC. What energy is stored at 8.0 V?', NULL, 2, 'multiple_choice'::answer_type, '16 mJ', NULL, false, NULL, false, NULL, 'Energy = area of triangle = ½ × 4.0 × 10⁻³ × 8.0 = 0.016 J. 32 mJ uses QV without the ½. Mark scheme (3 marks). C1: area under V–Q graph. C1: ½QV. A1: C (16 mJ).', 3),
('8f2c1c47-689b-5189-b51f-966adfe303bf', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1f2d9fae-c676-5618-9e77-df3b1c100686', 'a-level', '23.2', '9702 coursebook 23.2 · Energy stored in a capacitor', 30, 30, 'A 4700 µF capacitor discharges from 9.0 V to 3.0 V. Calculate the energy it releases.', NULL, 2, 'numeric'::answer_type, '0.1692', 'J', false, NULL, false, NULL, 'ΔW = 0.5 × 4700 × 10⁻⁶ × (9.0² − 3.0²) = 0.169 J. Mark scheme (3 marks). M1: difference of ½CV². C1: substitution. A1: ΔW = 0.169 J.', 3),
('34e4272f-afbd-5449-9ce5-c55db82fddc1', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1f2d9fae-c676-5618-9e77-df3b1c100686', 'a-level', '23.2', '9702 coursebook 23.2 · Energy stored in a capacitor', 31, 31, 'A camera flash uses a 150 µF capacitor charged to 330 V for each flash. Its battery stores 1.0 × 10⁴ J, and charging the capacitor is 60 % efficient. Estimate the number of flashes the battery can provide.', NULL, 2, 'numeric'::answer_type, '734.6', NULL, false, NULL, false, NULL, 'Energy per flash = 0.5 × 150 × 10⁻⁶ × 330² = 8.17 J. Useful energy = 0.60 × 1.0 × 10⁴ = 6000 J. Number = 6000 ÷ 8.167 = 735. Mark scheme (4 marks). C1: ½CV² per flash. C1: 60 % of battery energy. C1: number = useful energy ÷ energy per flash. A1: number = 735.', 4),
('0545fb60-6d74-5810-a780-1bea1a1addba', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1f2d9fae-c676-5618-9e77-df3b1c100686', 'a-level', '23.2', '9702 coursebook 23.2 · Energy stored in a capacitor', 32, 32, 'Capacitor A has capacitance C and is charged to 2V. Capacitor B has capacitance 2C and is charged to V. What is (energy in A) ÷ (energy in B)?', NULL, 2, 'multiple_choice'::answer_type, '2', NULL, false, NULL, false, NULL, 'W_A = ½C(2V)² = 2CV²; W_B = ½(2C)V² = CV²; the ratio is 2. Mark scheme (4 marks). C1: W_A = 2CV². C1: W_B = CV². C1: ratio. A1: A (2).', 4),
('d55ad58b-b111-5907-b056-ab4cf3d385c1', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1f2d9fae-c676-5618-9e77-df3b1c100686', 'a-level', '23.2', '9702 coursebook 23.2 · Energy stored in a capacitor', 33, 33, 'A capacitor stores 0.36 J of energy when the p.d. across it is 12 V. Calculate the charge on it.', NULL, 2, 'numeric'::answer_type, '0.06', 'C', false, NULL, false, NULL, 'W = ½QV, so Q = 2W/V = 2 × 0.36 ÷ 12 = 0.060 C. Mark scheme (3 marks). C1: W = ½QV. C1: rearranged. A1: Q = 0.060 C.', 3),
('7ad51a28-0fc8-583d-a81e-7c35e9823d62', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1f2d9fae-c676-5618-9e77-df3b1c100686', 'a-level', '23.2', '9702 coursebook 23.2 · Energy stored in a capacitor', 34, 34, 'A 0.10 F capacitor charged to 5.0 V powers a clock that needs 2.0 mW. The clock stops working when the p.d. falls to 2.0 V. Assuming constant power, estimate how long the clock runs.', NULL, 2, 'numeric'::answer_type, '525', 's', false, NULL, false, NULL, 'Energy available = 0.5 × 0.10 × (5.0² − 2.0²) = 1.05 J. t = W/P = 1.05 ÷ 2.0 × 10⁻³ = 525 s. Mark scheme (4 marks). C1: ½CV² at each p.d. M1: energy difference available. C1: t = W/P. A1: t = 525 s.', 4),
('854919ef-88b1-5b42-9610-e1d9c706d241', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1f2d9fae-c676-5618-9e77-df3b1c100686', 'a-level', '23.2', '9702 coursebook 23.2 · Energy stored in a capacitor', 35, 35, 'A capacitor is charged from zero by a constant current. How does the energy stored vary with time?', NULL, 2, 'multiple_choice'::answer_type, 'In proportion to t², because V ∝ t and W ∝ V²', NULL, false, NULL, false, NULL, 'Q = It, so V = It/C and W = ½CV² = I²t²/2C. Mark scheme (3 marks). C1: V ∝ t. C1: W ∝ V². A1: D (In proportion to t², because V ∝ t and W ∝ V²).', 3),
('ad619527-59db-555e-9d2d-467cfdee09da', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1f2d9fae-c676-5618-9e77-df3b1c100686', 'a-level', '23.2', '9702 coursebook 23.2 · Energy stored in a capacitor', 36, 36, 'Calculate the charge on a 2000 µF capacitor that stores 50 J.', NULL, 2, 'numeric'::answer_type, '0.4472', 'C', false, NULL, false, NULL, 'W = Q²/2C, so Q = √(2WC) = √(2 × 50 × 2000 × 10⁻⁶) = 0.447 C. Mark scheme (3 marks). C1: W = Q²/2C. C1: rearranged. A1: Q = 0.447 C.', 3),
('0867e14f-c5ad-56a7-af47-2e13764bc6ea', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1f2d9fae-c676-5618-9e77-df3b1c100686', 'a-level', '23.2', '9702 coursebook 23.2 · Energy stored in a capacitor', 37, 37, 'The p.d. across a capacitor is increased from 4.0 V to 12 V. By what factor does the energy stored increase?', NULL, 2, 'numeric'::answer_type, '9', NULL, false, NULL, false, NULL, 'W ∝ V², so the factor = (12 ÷ 4.0)² = 9.0. Mark scheme (3 marks). C1: W ∝ V². C1: ratio squared. A1: factor = 9.0.', 3),
('16d4ce8d-68fa-56b9-9609-2ca5f14b5128', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1f2d9fae-c676-5618-9e77-df3b1c100686', 'a-level', '23.2', '9702 coursebook 23.2 · Energy stored in a capacitor', 38, 38, 'A defibrillator delivers 360 J to a patient in 5.0 ms. Calculate the average power delivered, in kW.', NULL, 2, 'numeric'::answer_type, '72 kW', 'kW', false, NULL, false, NULL, 'P = W/t = 360 ÷ 5.0 × 10⁻³ = 7.2 × 10⁴ W. In kW: 7.2 × 10⁴ ÷ 1000 = 72. Mark scheme (4 marks). C1: P = W/t. C1: t in s. C1: conversion to kW. A1: P = 72 kW.', 4),
('8a88a6d6-4b5c-59de-ad0f-26f349662217', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1f2d9fae-c676-5618-9e77-df3b1c100686', 'a-level', '23.2', '9702 coursebook 23.2 · Energy stored in a capacitor', 39, 39, 'A capacitor is connected to a fixed supply. Which change would exactly double the energy stored?', NULL, 2, 'multiple_choice'::answer_type, 'Doubling the capacitance', NULL, false, NULL, false, NULL, 'At fixed V, W = ½CV² ∝ C. Doubling V or Q at fixed C quadruples W. Mark scheme (3 marks). C1: W ∝ C at fixed V. C1: W ∝ V² rules out the others. A1: B (Doubling the capacitance).', 3),
('41bebdd5-c4bd-5180-90db-aa4aef0ae8e3', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1f2d9fae-c676-5618-9e77-df3b1c100686', 'a-level', '23.2', '9702 coursebook 23.2 · Energy stored in a capacitor', 40, 40, 'A thundercloud and the ground act as a capacitor of 1.0 × 10⁻⁷ F charged to 1.0 × 10⁸ V. Calculate the energy stored.', NULL, 2, 'numeric'::answer_type, '5e8', 'J', false, NULL, false, NULL, 'W = ½CV² = 0.5 × 1.0 × 10⁻⁷ × (1.0 × 10⁸)² = 5.0 × 10⁸ J. Mark scheme (3 marks). C1: W = ½CV². C1: substitution. A1: W = 5.0 × 10⁸ J.', 3),
('b8186250-b80d-5e93-ae77-a7c267e07404', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1f2d9fae-c676-5618-9e77-df3b1c100686', 'a-level', '23.2', '9702 coursebook 23.2 · Energy stored in a capacitor', 41, 41, 'A 3000 F supercapacitor has a mass of 0.50 kg and can be charged to 2.7 V. Calculate the energy stored per kilogram of capacitor.', NULL, 2, 'numeric'::answer_type, '21870', 'J kg⁻¹', false, NULL, false, NULL, 'W = 0.5 × 3000 × 2.7² = 1.09 × 10⁴ J. Per kilogram: 1.094 × 10⁴ ÷ 0.50 = 2.19 × 10⁴ J kg⁻¹. Mark scheme (3 marks). C1: W = ½CV². C1: ÷ mass. A1: energy per kg = 2.19 × 10⁴ J kg⁻¹.', 3),
('625b9bdc-eaba-5b1f-8316-b8332654289b', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1f2d9fae-c676-5618-9e77-df3b1c100686', 'a-level', '23.2', '9702 coursebook 23.2 · Energy stored in a capacitor', 42, 42, 'A student charges a capacitor and records: V/V = 0, 2.5, 5.0, 7.5, 10.0 and Q/mC = 0, 1.1, 2.2, 3.3, 4.4. (a) Calculate the capacitance in µF. (b) Use the area under the V–Q graph to find the energy stored at 10.0 V. (c) Calculate the energy added as the p.d. rises from 5.0 V to 10.0 V, in mJ. (d) Explain why more energy is added in the second 5.0 V than in the first. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '16.5 mJ', 'mJ', false, NULL, false, NULL, '(a) C = Q/V = 4.4 × 10⁻³ ÷ 10.0 = 4.4 × 10⁻⁴ F, which is 440 µF. (b) Area = 0.5 × 4.4 × 10⁻³ × 10.0 = 0.022 J. (c) At 5.0 V: 0.5 × 2.2 × 10⁻³ × 5.0 = 0.0055 J. ΔW = 0.022 − 0.0055 = 0.0165 J. In mJ: 0.0165 × 1000 = 16.5. (d) Each extra coulomb is pushed on against a larger p.d., so more work is done per coulomb. Mark scheme (6 marks). C1: C = gradient. C1: area of triangle. C1: energy at 5.0 V. M1: difference of areas. B1: work per coulomb rises with V. A1: ΔW = 16.5 mJ.', 6),
('b03c16ff-701a-5a7e-b5a2-af91eef873bd', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1f2d9fae-c676-5618-9e77-df3b1c100686', 'a-level', '23.2', '9702 coursebook 23.2 · Energy stored in a capacitor', 43, 43, 'A 100 µF capacitor charged to 12 V is connected across an uncharged 50 µF capacitor. (a) Calculate the initial energy stored. (b) Calculate the common p.d. after connection. (c) Calculate the total energy stored after connection. (d) Calculate the energy lost, in mJ, and state where it goes. Give only the energy lost.', NULL, 3, 'numeric'::answer_type, '2.4 mJ', 'mJ', false, NULL, false, NULL, '(a) W₁ = 0.5 × 100 × 10⁻⁶ × 12² = 7.2 × 10⁻³ J. (b) Charge is conserved: Q = 100 × 10⁻⁶ × 12 = 1.2 × 10⁻³ C, so V = 1.2 × 10⁻³ ÷ 150 × 10⁻⁶ = 8.0 V. (c) W₂ = 0.5 × 150 × 10⁻⁶ × 8.0² = 4.8 × 10⁻³ J. (d) Loss = 7.2 × 10⁻³ − 4.8 × 10⁻³ = 2.4 × 10⁻³ J. In mJ: 2.4 × 10⁻³ × 1000 = 2.4. It is dissipated as heat in the connecting wires (and some as electromagnetic radiation). Mark scheme (6 marks). C1: initial ½CV². M1: charge conserved. C1: common V. C1: final energy. B1: heating in wires. A1: W = 2.4 mJ.', 6),
('a5a888de-4607-59f7-8285-3c1726b863a2', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1f2d9fae-c676-5618-9e77-df3b1c100686', 'a-level', '23.2', '9702 coursebook 23.2 · Energy stored in a capacitor', 44, 44, 'A defibrillator must deliver 150 J from a 50 µF capacitor. (a) Calculate the p.d. to which the capacitor must be charged. (b) Calculate the charge stored. (c) The capacitor discharges through the patient in 4.0 ms. Calculate the average current. Give only the answer to (a).', NULL, 3, 'numeric'::answer_type, '2449', 'V', false, NULL, false, NULL, '(a) V = √(2W/C) = √(2 × 150 ÷ 50 × 10⁻⁶) = 2450 V. (b) Q = CV = 50 × 10⁻⁶ × 2449 = 0.122 C. (c) I = Q/t = 0.1225 ÷ 4.0 × 10⁻³ = 30.6 A. Mark scheme (5 marks). C1: V = √(2W/C). C1: Q = CV. C1: I = Q/t. M1: rearrangement of W = ½CV². A1: V = 2450 V.', 5),
('49adb26b-f672-53c0-9965-4b2ce3a83926', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1f2d9fae-c676-5618-9e77-df3b1c100686', 'a-level', '23.2', '9702 coursebook 23.2 · Energy stored in a capacitor', 45, 45, '(a) Use a graph of p.d. against charge to show that the energy stored in a capacitor is ½CV². (b) A pulsed laser uses a 2.0 µF capacitor charged to 6.0 kV. Calculate the energy stored. (c) The capacitor is charged in 3.0 s by a constant current. Calculate this current, in mA. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '4 mA', 'mA', false, NULL, false, NULL, '(a) The graph is a straight line from the origin to (Q, V); the energy is the area ½QV, and Q = CV gives ½CV². (b) W = 0.5 × 2.0 × 10⁻⁶ × (6.0 × 10³)² = 36 J. (c) Q = CV = 2.0 × 10⁻⁶ × 6.0 × 10³ = 0.012 C. I = Q/t = 0.012 ÷ 3.0 = 4.0 × 10⁻³ A. In mA: 4.0 × 10⁻³ × 1000 = 4.0. Mark scheme (5 marks). M1: area under V–Q graph. B1: ½QV = ½CV². C1: energy. C1: Q = CV then I = Q/t. A1: I = 4.0 mA.', 5),
('b97a2988-46c7-55cf-b92a-553daa605dd5', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1f2d9fae-c676-5618-9e77-df3b1c100686', 'a-level', '23.2', '9702 coursebook 23.2 · Energy stored in a capacitor', 46, 46, 'A camera flash circuit charges a 220 µF capacitor to 300 V. (a) Calculate the charge stored. (b) Calculate the energy stored. (c) The flash lasts 1.0 ms. Calculate the average power of the flash, in kW. (d) Explain why the flash tube is not powered directly from the 1.5 V battery. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '9.9 kW', 'kW', false, NULL, false, NULL, '(a) Q = 220 × 10⁻⁶ × 300 = 0.0660 C. (b) W = 0.5 × 220 × 10⁻⁶ × 300² = 9.90 J. (c) P = 9.90 ÷ 1.0 × 10⁻³ = 9900 W. In kW: 9900 ÷ 1000 = 9.90. (d) The battery''s internal resistance and low p.d. cannot supply such a large power; the capacitor collects energy slowly and releases it quickly. Mark scheme (5 marks). C1: Q = CV. C1: W = ½CV². C1: P = W/t. B1: battery cannot deliver high power. A1: P = 9.90 kW.', 5),
('38727c2c-003f-5617-b63b-fb7ec86b8bbc', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1f2d9fae-c676-5618-9e77-df3b1c100686', 'a-level', '23.2', '9702 coursebook 23.2 · Energy stored in a capacitor', 47, 47, 'A student measures the energy stored in a capacitor at several p.d.s: V/V = 2.0, 4.0, 6.0, 8.0 and W/mJ = 0.94, 3.76, 8.46, 15.0. (a) Explain why a graph of W against V² should be a straight line through the origin. (b) Calculate W/V² for the first and last readings. (c) Use the gradient to calculate the capacitance, in µF. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '468.8', 'µF', false, NULL, false, ARRAY['4.688e-4']::text[], '(a) W = ½CV², so W ∝ V² with gradient C/2. (b) 0.94 × 10⁻³ ÷ 2.0² = 2.35 × 10⁻⁴ J V⁻² and 15.0 × 10⁻³ ÷ 8.0² = 2.34 × 10⁻⁴ J V⁻², the same within experimental error. (c) C = 2 × gradient = 2 × 2.344 × 10⁻⁴ = 4.69 × 10⁻⁴ F. In µF: 4.687 × 10⁻⁴ × 10⁶ = 469. Mark scheme (6 marks). M1: W = ½CV² so gradient C/2. C1: W/V² values. B1: constant within error. C1: C = 2 × gradient. C1: conversion to µF. A1: C = 469 µF.', 6),
('f6e19c48-1c92-5665-bfd9-cb9451be2eed', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1f2d9fae-c676-5618-9e77-df3b1c100686', 'a-level', '23.2', '9702 coursebook 23.2 · Energy stored in a capacitor', 48, 48, 'An 80 pF parallel-plate capacitor (C = ε₀A/d) is charged to 250 V and disconnected. Its plates are then pulled apart until the separation is three times as large. (a) Calculate the initial energy stored. (b) Calculate the new capacitance and the new energy stored. (c) Calculate the work done in pulling the plates apart, in µJ. (d) Explain where this work comes from. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '5 uJ', 'µJ', false, NULL, false, NULL, '(a) W₁ = 0.5 × 80 × 10⁻¹² × 250² = 2.50 × 10⁻⁶ J. (b) C₂ = 80 ÷ 3 = 26.7 pF. Q = 80 × 10⁻¹² × 250 = 2.0 × 10⁻⁸ C is unchanged, so W₂ = (2.0 × 10⁻⁸)² ÷ (2 × 2.667 × 10⁻¹¹) = 7.50 × 10⁻⁶ J. (c) Work = 7.500 × 10⁻⁶ − 2.500 × 10⁻⁶ = 5.00 × 10⁻⁶ J. In µJ: 5.000 × 10⁻⁶ × 10⁶ = 5.00. (d) The plates attract each other, so whoever pulls them apart does work against this force; that work becomes stored energy. Mark scheme (6 marks). C1: initial ½CV². C1: C ∝ 1/d. M1: Q constant so W = Q²/2C. C1: energy difference. B1: work against attraction of plates. A1: W = 5.00 µJ.', 6),
('272cfc7c-8a18-5a1f-8051-63f0e96a7f27', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1f2d9fae-c676-5618-9e77-df3b1c100686', 'a-level', '23.2', '9702 coursebook 23.2 · Energy stored in a capacitor', 49, 49, 'A small electric car stores braking energy in a supercapacitor bank of 60 F that can be charged to 48 V. The car has a mass of 1200 kg. (a) Calculate the maximum energy the bank can store. (b) Calculate the highest speed from which the car could be braked to rest with all its kinetic energy stored in the bank. (c) Suggest one reason why, in practice, less energy is recovered. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '10.73', 'm s⁻¹', false, NULL, false, NULL, '(a) W = 0.5 × 60 × 48² = 6.91 × 10⁴ J. (b) ½mv² = W, so v = √(2 × 6.912 × 10⁴ ÷ 1200) = 10.7 m s⁻¹. (c) Energy is lost as heat in the motor-generator, wiring and capacitor resistance, and some by friction in the brakes and tyres. Mark scheme (6 marks). C1: W = ½CV². M1: ½mv² = W. C1: rearranged for v. C1: substitution. B1: resistive or friction losses. A1: v = 10.7 m s⁻¹.', 6),
('fb48603a-31eb-5028-8758-252b2e64d0da', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1f2d9fae-c676-5618-9e77-df3b1c100686', 'a-level', '23.2', '9702 coursebook 23.2 · Energy stored in a capacitor', 50, 50, 'A 470 µF capacitor charged to 12 V discharges until it has lost half of its stored energy. (a) Calculate the initial energy. (b) Calculate the p.d. when half the energy remains. (c) Calculate the charge that has flowed off the capacitor by then, in mC. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '1.652 mC', 'mC', false, NULL, false, NULL, '(a) W = 0.5 × 470 × 10⁻⁶ × 12² = 0.0338 J. (b) W ∝ V², so V = 12 ÷ √2 = 8.49 V. (c) ΔQ = CΔV = 470 × 10⁻⁶ × (12 − 8.485) = 0.00165 C. In mC: 0.001652 × 1000 = 1.65. Mark scheme (5 marks). C1: initial energy. M1: V ∝ √W. C1: ΔQ = CΔV. C1: conversion to mC. A1: ΔQ = 1.65 mC.', 5)
