('20413c2b-9b2d-58e9-a1c9-0beec50ab9e8', '7fc846b3-593a-5c4e-8376-f9aa2a29d6b4', 'None of it', 'D', false, 3),
('08c6148d-3bed-58e2-aac0-966c8cf30dbd', '5e52579b-acdd-549f-b826-3fb47356181a', 'A straight line through the origin', 'A', false, 0),
