('e66192fc-36ee-505f-85c2-9935b0d674af', '52383281-e7d0-51e0-98ec-ec8fa2b02162', 'In the wires connecting it', 'B', false, 1),
('cbd1eddf-16ab-5144-9b24-76a405e458fd', '52383281-e7d0-51e0-98ec-ec8fa2b02162', 'In the metal of the plates as heat', 'C', false, 2),
