('e7b859df-89c2-5e30-bd47-8f9ffd0877dd', '7a63f444-89b5-5486-8f9a-5d4bbf8b27a3', 'It halves', 'A', false, 0),
('4cdf8756-a9a7-5e4e-bc27-ae30a90e9a67', '7a63f444-89b5-5486-8f9a-5d4bbf8b27a3', 'It doubles', 'B', false, 1),
('ada7bd3b-a5f5-517c-a216-179e0e23aa74', '7a63f444-89b5-5486-8f9a-5d4bbf8b27a3', 'It stays the same', 'C', false, 2),
('d366c6e9-2334-506a-a190-adc53b7876bd', '7a63f444-89b5-5486-8f9a-5d4bbf8b27a3', 'It becomes one quarter of its original value', 'D', true, 3),
('dd874bc3-5eda-5a69-a848-1ee26b593030', '2dc3f2be-d415-57f1-8add-fc2178298922', 'It stores much more energy', 'A', false, 0),
('aaa368b3-32e9-5d59-b16e-1ba55f55f20f', '2dc3f2be-d415-57f1-8add-fc2178298922', 'It can release its energy very quickly', 'B', true, 1),
('779ed908-7350-5443-80f4-63ff011ae873', '2dc3f2be-d415-57f1-8add-fc2178298922', 'It keeps a constant p.d. as it discharges', 'C', false, 2),
('a7adaa3f-5ee3-55c0-b839-556a292b5409', '2dc3f2be-d415-57f1-8add-fc2178298922', 'It never loses charge', 'D', false, 3),
('9efe130d-3bdc-5753-bb3a-1cb156fc38d8', '01b5f306-f721-5700-9495-15b66af936cd', '32 mJ', 'A', false, 0),
('2d1497d7-e420-5c0c-8620-cc191a7c04f6', '01b5f306-f721-5700-9495-15b66af936cd', '8.0 mJ', 'B', false, 1),
('4f163145-ac36-5734-9344-1eb7cb58d780', '01b5f306-f721-5700-9495-15b66af936cd', '16 mJ', 'C', true, 2),
('273fe691-6a71-524b-ac99-95e6cd02ca54', '01b5f306-f721-5700-9495-15b66af936cd', '0.50 mJ', 'D', false, 3),
('3ff1ad92-da09-5a18-a536-153ee9aa2ee2', '0545fb60-6d74-5810-a780-1bea1a1addba', '2', 'A', true, 0),
