('7b2f67d7-0afb-531e-bac0-8950da491282', '0545fb60-6d74-5810-a780-1bea1a1addba', '4', 'D', false, 3),
('dba79f4c-07b9-5ec8-a74c-4cde3be8d0ec', '854919ef-88b1-5b42-9610-e1d9c706d241', 'In proportion to t', 'A', false, 0),
('9befa593-a5c3-5c18-bb41-6f7350764ae5', '854919ef-88b1-5b42-9610-e1d9c706d241', 'It stays constant', 'B', false, 1),
('46168fd2-171a-5a1b-9f06-dc7ba3ff1d51', '854919ef-88b1-5b42-9610-e1d9c706d241', 'In proportion to √t', 'C', false, 2),
('fd0efada-e541-5b87-a5c4-9ac1fb1d9b51', '854919ef-88b1-5b42-9610-e1d9c706d241', 'In proportion to t², because V ∝ t and W ∝ V²', 'D', true, 3),
('6ae4ab63-198c-5d01-9871-3adfad86afb8', '8a88a6d6-4b5c-59de-ad0f-26f349662217', 'Doubling the p.d.', 'A', false, 0),
('6893e4e8-609e-50ec-94ac-39052e0efba3', '8a88a6d6-4b5c-59de-ad0f-26f349662217', 'Doubling the capacitance', 'B', true, 1),
('9f1a3078-4c09-5b9c-abdd-03606cec36d0', '8a88a6d6-4b5c-59de-ad0f-26f349662217', 'Halving the capacitance', 'C', false, 2),
('62ca5b15-643e-5ee6-a37a-51475f364657', '8a88a6d6-4b5c-59de-ad0f-26f349662217', 'Doubling the charge with the same capacitance', 'D', false, 3)
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points) VALUES
('f4c4cc8a-40f2-5292-99cf-a96ca36504bd', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1da133f6-6b3d-48ce-9d65-eff20177efd9', 'a-level', '23.3', '9702 coursebook 23.3 · Capacitors in parallel', 7, 7, 'Capacitors are connected in parallel across a supply. How is the total charge drawn from the supply related to the charges on the individual capacitors?', NULL, 1, 'multiple_choice'::answer_type, 'It is the sum of the individual charges', NULL, false, NULL, false, NULL, 'Each capacitor takes its own charge from the supply, so Q = Q₁ + Q₂ + …. Mark scheme (1 mark). B1: C (It is the sum of the individual charges).', 1),
('e4ae7708-0208-56fa-8be3-177c99039df1', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1da133f6-6b3d-48ce-9d65-eff20177efd9', 'a-level', '23.3', '9702 coursebook 23.3 · Capacitors in parallel', 8, 8, 'A 220 µF capacitor and a 470 µF capacitor are connected in parallel. Calculate the combined capacitance in µF.', NULL, 1, 'numeric'::answer_type, '690', 'µF', false, NULL, false, ARRAY['6.9e-4']::text[], 'C = C₁ + C₂ = 220 + 470 = 690 µF. Mark scheme (2 marks). C1: C = C₁ + C₂. A1: C = 690 µF.', 2),
('1ec12bed-c97c-5bd5-b7df-155b02e61461', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1da133f6-6b3d-48ce-9d65-eff20177efd9', 'a-level', '23.3', '9702 coursebook 23.3 · Capacitors in parallel', 9, 9, 'Four 25 µF capacitors are connected in parallel. Calculate their combined capacitance in µF.', NULL, 1, 'numeric'::answer_type, '100', 'µF', false, NULL, false, ARRAY['1e-4']::text[], 'Capacitances add in parallel: C = 4 × 25 = 100 µF. Mark scheme (2 marks). C1: capacitances add in parallel. A1: C = 100 µF.', 2),
('8b86df24-e1b5-5ea5-afe3-5b9e337b520f', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1da133f6-6b3d-48ce-9d65-eff20177efd9', 'a-level', '23.3', '9702 coursebook 23.3 · Capacitors in parallel', 10, 10, 'Which formula gives the total capacitance C of capacitors C₁, C₂ and C₃ connected in parallel?', NULL, 1, 'multiple_choice'::answer_type, 'C = C₁ + C₂ + C₃', NULL, false, NULL, false, NULL, 'In parallel the p.d. is common and the charges add, so the capacitances add. Mark scheme (1 mark). B1: A (C = C₁ + C₂ + C₃).', 1),
('f913a824-ec29-5a73-b2f6-bc25cf9f7355', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1da133f6-6b3d-48ce-9d65-eff20177efd9', 'a-level', '23.3', '9702 coursebook 23.3 · Capacitors in parallel', 11, 11, 'Across a 9.0 V supply, a 33 µF capacitor sits alongside two other capacitors in parallel. Find the charge on the 33 µF capacitor, in µC.', NULL, 1, 'numeric'::answer_type, '297 uC', 'µC', false, NULL, false, NULL, 'Each capacitor has the full 9.0 V across it: Q = CV = 33 × 10⁻⁶ × 9.0 = 2.97 × 10⁻⁴ C. In µC: 2.97 × 10⁻⁴ × 10⁶ = 297. Mark scheme (2 marks). C1: full supply p.d. across each. A1: Q = 297 µC.', 2),
('9bbd4ef4-f869-5225-833d-b95229f86fca', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1da133f6-6b3d-48ce-9d65-eff20177efd9', 'a-level', '23.3', '9702 coursebook 23.3 · Capacitors in parallel', 12, 12, 'Another capacitor is connected in parallel with a capacitor already across a battery. What happens to the total charge drawn from the battery?', NULL, 1, 'multiple_choice'::answer_type, 'It increases', NULL, false, NULL, false, NULL, 'Total capacitance increases and V is fixed, so Q = CV increases. Mark scheme (1 mark). B1: D (It increases).', 1),
('c01610f8-38f3-5ff6-ae68-a9063d57bbc5', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1da133f6-6b3d-48ce-9d65-eff20177efd9', 'a-level', '23.3', '9702 coursebook 23.3 · Capacitors in parallel', 13, 13, 'A designer needs extra capacitance and wires two 47 µF capacitors alongside a 100 µF capacitor, all in parallel. What is the total, in µF?', NULL, 1, 'numeric'::answer_type, '194', 'µF', false, NULL, false, ARRAY['1.94e-4']::text[], 'C = 47 + 47 + 100 = 194 µF. Mark scheme (2 marks). C1: sum of capacitances. A1: C = 194 µF.', 2),
('bde92a7f-1acb-5943-9956-96a3312c8279', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1da133f6-6b3d-48ce-9d65-eff20177efd9', 'a-level', '23.3', '9702 coursebook 23.3 · Capacitors in parallel', 14, 14, 'In a parallel combination of different capacitors connected to a supply, which capacitor stores the most charge?', NULL, 1, 'multiple_choice'::answer_type, 'The one with the largest capacitance', NULL, false, NULL, false, NULL, 'They share the same p.d., so Q = CV is largest for the largest C. Mark scheme (1 mark). B1: B (The one with the largest capacitance).', 1),
('57c0a796-6572-5284-b4da-796a04af0173', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1da133f6-6b3d-48ce-9d65-eff20177efd9', 'a-level', '23.3', '9702 coursebook 23.3 · Capacitors in parallel', 15, 15, 'Capacitors of 2.0 µF, 3.0 µF and 5.0 µF are connected in parallel across a 6.0 V supply. Calculate the total charge stored, in µC.', NULL, 1, 'numeric'::answer_type, '60 uC', 'µC', false, NULL, false, NULL, 'C = 2.0 + 3.0 + 5.0 = 10 µF. Q = CV = 10 × 10⁻⁶ × 6.0 = 6.0 × 10⁻⁵ C. In µC: 6.0 × 10⁻⁵ × 10⁶ = 60. Mark scheme (2 marks). C1: total C then Q = CV. A1: Q = 60 µC.', 2),
('a3d4ed9d-484f-59fa-b005-3b799bd90626', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1da133f6-6b3d-48ce-9d65-eff20177efd9', 'a-level', '23.3', '9702 coursebook 23.3 · Capacitors in parallel', 16, 16, 'In a parallel combination, one capacitor is replaced by one of larger capacitance. What happens to the total capacitance?', NULL, 1, 'multiple_choice'::answer_type, 'It increases', NULL, false, NULL, false, NULL, 'C = C₁ + C₂ + …, so increasing any term increases the sum. Mark scheme (1 mark). B1: C (It increases).', 1),
('eeac2ed2-dbba-5378-b085-6ece074b8753', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1da133f6-6b3d-48ce-9d65-eff20177efd9', 'a-level', '23.3', '9702 coursebook 23.3 · Capacitors in parallel', 17, 17, 'Two 100 µF capacitors are connected in parallel across 10 V. Calculate the total energy stored.', NULL, 1, 'numeric'::answer_type, '0.01', 'J', false, NULL, false, NULL, 'C = 200 µF. W = ½CV² = 0.5 × 200 × 10⁻⁶ × 10² = 0.010 J. Mark scheme (2 marks). C1: total C and W = ½CV². A1: W = 0.010 J.', 2),
('90a790be-1535-5ab4-939f-a189b65fa0e8', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1da133f6-6b3d-48ce-9d65-eff20177efd9', 'a-level', '23.3', '9702 coursebook 23.3 · Capacitors in parallel', 18, 18, 'Two identical capacitors, each of capacitance C, are connected in parallel. What is the combined capacitance?', NULL, 1, 'multiple_choice'::answer_type, '2C', NULL, false, NULL, false, NULL, 'Capacitances add in parallel. Mark scheme (1 mark). B1: A (2C).', 1),
('38acc23f-c54a-51dc-a7a2-a4545d1f3358', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1da133f6-6b3d-48ce-9d65-eff20177efd9', 'a-level', '23.3', '9702 coursebook 23.3 · Capacitors in parallel', 19, 19, 'Calculate the total capacitance of a 1.0 µF capacitor and a 0.47 µF capacitor in parallel, in µF.', NULL, 1, 'numeric'::answer_type, '1.47', 'µF', false, NULL, false, ARRAY['1.47e-6']::text[], 'C = 1.0 + 0.47 = 1.47 µF. Mark scheme (1 mark). A1: C = 1.47 µF.', 1),
('189b4bd2-04f4-5953-a08b-b5cb3dc2dc95', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1da133f6-6b3d-48ce-9d65-eff20177efd9', 'a-level', '23.3', '9702 coursebook 23.3 · Capacitors in parallel', 20, 20, 'How does the total capacitance of a parallel combination compare with the largest capacitance in it?', NULL, 1, 'multiple_choice'::answer_type, 'It is greater than the largest capacitance', NULL, false, NULL, false, NULL, 'Adding positive terms always gives a total bigger than any one term. Mark scheme (1 mark). B1: D (It is greater than the largest capacitance).', 1),
('9d0012a9-9025-52dc-8ea5-d213ebf7bdfc', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1da133f6-6b3d-48ce-9d65-eff20177efd9', 'a-level', '23.3', '9702 coursebook 23.3 · Capacitors in parallel', 21, 21, 'A 3.0 µF capacitor and a 7.0 µF capacitor are in parallel and together hold a total charge of 50 µC. Calculate the p.d. across them.', NULL, 1, 'numeric'::answer_type, '5', 'V', false, NULL, false, NULL, 'C = 3.0 + 7.0 = 10 µF. V = Q/C = 50 × 10⁻⁶ ÷ 10 × 10⁻⁶ = 5.0 V. Mark scheme (2 marks). C1: V = Q/C with total C. A1: V = 5.0 V.', 2),
('35abe8de-02cd-537e-9e37-4ae60bacb7ab', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1da133f6-6b3d-48ce-9d65-eff20177efd9', 'a-level', '23.3', '9702 coursebook 23.3 · Capacitors in parallel', 22, 22, 'Connecting two identical parallel-plate capacitors in parallel has the same effect as which change to one of them?', NULL, 1, 'multiple_choice'::answer_type, 'Doubling the area of its plates', NULL, false, NULL, false, NULL, 'C ∝ A: side-by-side plates act as one plate of twice the area. Mark scheme (1 mark). B1: B (Doubling the area of its plates).', 1),
('4bb6beed-4a5f-5e8a-8bfe-eb3f243181e7', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1da133f6-6b3d-48ce-9d65-eff20177efd9', 'a-level', '23.3', '9702 coursebook 23.3 · Capacitors in parallel', 23, 23, 'A 10 µF capacitor and a 40 µF capacitor are connected in parallel to a supply. Calculate (charge on 10 µF) ÷ (charge on 40 µF).', NULL, 1, 'numeric'::answer_type, '0.25', NULL, false, NULL, false, NULL, 'Same p.d., so Q ∝ C: ratio = 10 ÷ 40 = 0.25. Mark scheme (2 marks). C1: Q ∝ C at the same V. A1: ratio = 0.25.', 2),
('f940b300-fbf0-5f63-aa50-04ada9a43caf', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1da133f6-6b3d-48ce-9d65-eff20177efd9', 'a-level', '23.3', '9702 coursebook 23.3 · Capacitors in parallel', 24, 24, 'A smoothing bank is made of twelve 2200 µF capacitors in parallel, charged to 16 V. Calculate the total charge stored.', NULL, 2, 'numeric'::answer_type, '0.4224', 'C', false, NULL, false, NULL, 'C = 12 × 2200 × 10⁻⁶ = 0.0264 F. Q = CV = 0.0264 × 16 = 0.422 C. Mark scheme (3 marks). C1: total C = 12 × 2200 µF. C1: Q = CV. A1: Q = 0.422 C.', 3),
('0e4d71c2-b21c-5e8e-829f-e34f8294ddae', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1da133f6-6b3d-48ce-9d65-eff20177efd9', 'a-level', '23.3', '9702 coursebook 23.3 · Capacitors in parallel', 25, 25, 'Capacitors of 10 µF and 20 µF are in parallel across a 6.0 V supply. A 30 µF capacitor is then added in parallel. Calculate the extra charge drawn from the supply, in µC.', NULL, 2, 'numeric'::answer_type, '180 uC', 'µC', false, NULL, false, NULL, 'Only the new capacitor needs charge, at the same 6.0 V: ΔQ = 30 × 10⁻⁶ × 6.0 = 1.8 × 10⁻⁴ C. In µC: 1.8 × 10⁻⁴ × 10⁶ = 180. Mark scheme (3 marks). C1: p.d. unchanged. C1: ΔQ = C_new × V. A1: ΔQ = 180 µC.', 3),
('fd82fb82-9cea-5f53-8e04-7e5325d4200c', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1da133f6-6b3d-48ce-9d65-eff20177efd9', 'a-level', '23.3', '9702 coursebook 23.3 · Capacitors in parallel', 26, 26, 'Which statement is the key step in showing that capacitances add in parallel?', NULL, 2, 'multiple_choice'::answer_type, 'The p.d. is the same across each capacitor, so Q = Q₁ + Q₂ gives CV = C₁V + C₂V', NULL, false, NULL, false, NULL, 'Dividing CV = C₁V + C₂V by V gives C = C₁ + C₂. Mark scheme (3 marks). C1: common V. C1: charges add. A1: C (The p.d. is the same across each capacitor, so Q = Q₁ + Q₂ gives CV = C₁V + C₂V).', 3),
('34bd54fd-ca64-58df-bfb8-9e9ba43b28c2', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1da133f6-6b3d-48ce-9d65-eff20177efd9', 'a-level', '23.3', '9702 coursebook 23.3 · Capacitors in parallel', 27, 27, 'A 20 µF capacitor charged to 9.0 V is disconnected from its supply and connected across an uncharged 10 µF capacitor. Calculate the final p.d. across the pair.', NULL, 2, 'numeric'::answer_type, '6', 'V', false, NULL, false, NULL, 'Charge is conserved: Q = 20 × 10⁻⁶ × 9.0 = 1.8 × 10⁻⁴ C. The pair is in parallel with C = 30 µF, so V = 1.8 × 10⁻⁴ ÷ 30 × 10⁻⁶ = 6.0 V. Mark scheme (4 marks). M1: total charge conserved. C1: capacitors in parallel, C = 30 µF. C1: V = Q/C. A1: V = 6.0 V.', 4),
('84954944-7964-558b-8ea8-33e6025f9bc0', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1da133f6-6b3d-48ce-9d65-eff20177efd9', 'a-level', '23.3', '9702 coursebook 23.3 · Capacitors in parallel', 28, 28, 'A 20 µF capacitor charged to 9.0 V is connected across an uncharged 10 µF capacitor, and the common p.d. becomes 6.0 V. Calculate the final charge on the 10 µF capacitor, in µC.', NULL, 2, 'numeric'::answer_type, '60 uC', 'µC', false, NULL, false, NULL, 'Q = CV = 10 × 10⁻⁶ × 6.0 = 6.0 × 10⁻⁵ C. In µC: 6.0 × 10⁻⁵ × 10⁶ = 60. Mark scheme (3 marks). C1: same p.d. across both. C1: Q = CV. A1: Q = 60 µC.', 3),
('db55ea20-d03a-5021-b39f-0e7de76d880d', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1da133f6-6b3d-48ce-9d65-eff20177efd9', 'a-level', '23.3', '9702 coursebook 23.3 · Capacitors in parallel', 29, 29, 'A charged capacitor is connected across an uncharged one. Which statement about the total charge and the total energy is correct?', NULL, 2, 'multiple_choice'::answer_type, 'Total charge is unchanged but total energy decreases', NULL, false, NULL, false, NULL, 'Charge is conserved; energy is lost as heat in the wires as charge flows between the capacitors. Mark scheme (3 marks). C1: charge conserved. C1: energy dissipated. A1: A (Total charge is unchanged but total energy decreases).', 3),
('aa18be36-1a29-58a7-9d10-e90bbed05f22', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1da133f6-6b3d-48ce-9d65-eff20177efd9', 'a-level', '23.3', '9702 coursebook 23.3 · Capacitors in parallel', 30, 30, 'A 47 µF capacitor and a 100 µF capacitor are connected in parallel across 12 V. Calculate the energy stored in the 47 µF capacitor, in mJ.', NULL, 2, 'numeric'::answer_type, '3.384 mJ', 'mJ', false, NULL, false, NULL, 'Each capacitor has 12 V across it: W = 0.5 × 47 × 10⁻⁶ × 12² = 0.00338 J. In mJ: 0.003384 × 1000 = 3.38. Mark scheme (3 marks). C1: full p.d. across each. C1: W = ½CV². A1: W = 3.38 mJ.', 3),
('d95643ad-173a-5770-9082-6dcb1873cf2f', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1da133f6-6b3d-48ce-9d65-eff20177efd9', 'a-level', '23.3', '9702 coursebook 23.3 · Capacitors in parallel', 31, 31, 'A capacitor bank must store a charge of 0.50 C when charged to 25 V. Calculate the total capacitance needed, in µF.', NULL, 2, 'numeric'::answer_type, '20000', 'µF', false, NULL, false, ARRAY['0.02']::text[], 'C = Q/V = 0.50 ÷ 25 = 0.020 F. In µF: 0.020 × 10⁶ = 20 000. Mark scheme (3 marks). C1: C = Q/V. C1: conversion to µF. A1: C = 2.0 × 10⁴ µF.', 3),
('f81d4dfb-e4de-5cbe-9f0e-787c92c42fc7', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1da133f6-6b3d-48ce-9d65-eff20177efd9', 'a-level', '23.3', '9702 coursebook 23.3 · Capacitors in parallel', 32, 32, 'A tiny 1.0 µF capacitor is added in parallel with a large 100 µF one. What is the combined capacitance?', NULL, 2, 'multiple_choice'::answer_type, 'About 101 µF: the small capacitor makes little difference', NULL, false, NULL, false, NULL, 'C = 100 + 1.0 = 101 µF. About 0.99 µF would be the series value. Mark scheme (3 marks). C1: C = C₁ + C₂. C1: series value is a distractor. A1: D (About 101 µF: the small capacitor makes little difference).', 3),
('7233b856-3f5b-5ea9-b62d-5f0816baedbd', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1da133f6-6b3d-48ce-9d65-eff20177efd9', 'a-level', '23.3', '9702 coursebook 23.3 · Capacitors in parallel', 33, 33, 'Capacitors of 22 µF, 47 µF and 33 µF are connected in parallel to a battery. Calculate the fraction of the total charge stored on the 22 µF capacitor.', NULL, 2, 'numeric'::answer_type, '0.2157', NULL, false, NULL, false, NULL, 'Q ∝ C at the same p.d., so fraction = 22 ÷ (22 + 47 + 33) = 0.216. Mark scheme (3 marks). C1: Q ∝ C. C1: ÷ total C. A1: fraction = 0.216.', 3),
('96018f22-3c89-5454-bb65-b74213d6e138', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1da133f6-6b3d-48ce-9d65-eff20177efd9', 'a-level', '23.3', '9702 coursebook 23.3 · Capacitors in parallel', 34, 34, 'Two capacitors in parallel across 12 V store charges of 120 µC and 360 µC. Calculate the total capacitance, in µF.', NULL, 2, 'numeric'::answer_type, '40', 'µF', false, NULL, false, ARRAY['4e-5']::text[], 'Q = 120 + 360 = 480 µC. C = Q/V = 480 × 10⁻⁶ ÷ 12 = 4.0 × 10⁻⁵ F. In µF: 4.0 × 10⁻⁵ × 10⁶ = 40. Mark scheme (3 marks). C1: charges add. C1: C = Q/V. A1: C = 40 µF.', 3),
('d91e574a-124d-5ff3-aa6d-63d8757495ee', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1da133f6-6b3d-48ce-9d65-eff20177efd9', 'a-level', '23.3', '9702 coursebook 23.3 · Capacitors in parallel', 35, 35, 'A capacitor of capacitance C charged to p.d. V is connected across an identical uncharged capacitor. Which row describes the final state?', NULL, 2, 'multiple_choice'::answer_type, 'p.d. V/2; total energy half the original', NULL, false, NULL, false, NULL, 'Q is shared over 2C, so V/2. W = ½(2C)(V/2)² = ¼CV², half of ½CV². Mark scheme (4 marks). C1: charge conserved. C1: final V = V/2. C1: energy ¼CV². A1: B (p.d. V/2; total energy half the original).', 4),
('8cbfee86-c948-5e17-b643-97d21da9543c', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1da133f6-6b3d-48ce-9d65-eff20177efd9', 'a-level', '23.3', '9702 coursebook 23.3 · Capacitors in parallel', 36, 36, 'Three 4.7 µF capacitors are connected in parallel across a 9.0 V supply. Calculate the total energy stored, in mJ.', NULL, 2, 'numeric'::answer_type, '0.5711 mJ', 'mJ', false, NULL, false, NULL, 'C = 3 × 4.7 = 14.1 µF. W = 0.5 × 14.1 × 10⁻⁶ × 9.0² = 5.71 × 10⁻⁴ J. In mJ: 5.711 × 10⁻⁴ × 1000 = 0.571. Mark scheme (3 marks). C1: total C. C1: W = ½CV². A1: W = 0.571 mJ.', 3),
('e2ba2918-f2ec-51d0-9cf5-50183a6e44ea', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1da133f6-6b3d-48ce-9d65-eff20177efd9', 'a-level', '23.3', '9702 coursebook 23.3 · Capacitors in parallel', 37, 37, 'Five identical capacitors connected in parallel have a combined capacitance of 235 µF. Calculate the capacitance of one of them, in µF.', NULL, 2, 'numeric'::answer_type, '47', 'µF', false, NULL, false, ARRAY['4.7e-5']::text[], 'C_total = 5C, so C = 235 ÷ 5 = 47 µF. Mark scheme (4 marks). M1: C_total = nC. C1: rearranged. C1: value. A1: C = 47 µF.', 4),
('db0aff4f-3261-5831-857e-0ed01ef6348e', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1da133f6-6b3d-48ce-9d65-eff20177efd9', 'a-level', '23.3', '9702 coursebook 23.3 · Capacitors in parallel', 38, 38, 'A 25 V-rated capacitor and a 16 V-rated capacitor are connected in parallel. What is the largest p.d. that can safely be applied to the combination?', NULL, 2, 'multiple_choice'::answer_type, '16 V', NULL, false, NULL, false, NULL, 'Both capacitors get the full p.d., so it must not exceed the lower rating. Mark scheme (3 marks). C1: same p.d. across each. C1: limited by lower rating. A1: C (16 V).', 3),
('f36ff41b-82d5-5161-a508-92d4e8dc1db4', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1da133f6-6b3d-48ce-9d65-eff20177efd9', 'a-level', '23.3', '9702 coursebook 23.3 · Capacitors in parallel', 39, 39, 'A parallel pair of capacitors stores 0.18 J at 30 V. One of them is 150 µF. Calculate the capacitance of the other, in µF.', NULL, 2, 'numeric'::answer_type, '250', 'µF', false, NULL, false, ARRAY['2.5e-4']::text[], 'C_total = 2W/V² = 2 × 0.18 ÷ 30² = 4.0 × 10⁻⁴ F, which is 400 µF. Other = 400 − 150 = 250 µF. Mark scheme (3 marks). C1: C = 2W/V². C1: subtract. A1: C = 250 µF.', 3),
('0621041a-d1ee-5d66-b6b6-50f5226b73ee', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1da133f6-6b3d-48ce-9d65-eff20177efd9', 'a-level', '23.3', '9702 coursebook 23.3 · Capacitors in parallel', 40, 40, 'A 470 µF capacitor is charged to 12 V and then connected across an uncharged 220 µF capacitor. (a) Calculate the charge on the 470 µF capacitor before connection. (b) Calculate the common p.d. after connection. (c) Show that the fraction of the original energy that remains is 470/690. (d) Calculate the percentage of the original energy that is lost. Give only the answer to (d), in %.', NULL, 3, 'numeric'::answer_type, '31.88', '%', false, NULL, false, NULL, '(a) Q = 470 × 10⁻⁶ × 12 = 0.00564 C. (b) V = 0.005640 ÷ 690 × 10⁻⁶ = 8.17 V. (c) W₂/W₁ = (Q²/2C₂) ÷ (Q²/2C₁) = C₁/C₂ = 470/690. (d) Loss = (1 − 470 ÷ 690) × 100 = 31.9 %. Mark scheme (6 marks). C1: Q = CV. C1: V = Q/(C₁ + C₂). M1: W = Q²/2C with Q fixed. B1: ratio C₁/C₂ shown. C1: percentage lost. A1: percentage = 31.9%.', 6),
('93a9a90d-25ab-56f7-ac7a-38ca9081e068', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1da133f6-6b3d-48ce-9d65-eff20177efd9', 'a-level', '23.3', '9702 coursebook 23.3 · Capacitors in parallel', 41, 41, 'A 10 µF capacitor C₁ is charged to 12 V and connected across an uncharged 20 µF capacitor C₂. C₂ is then disconnected and connected across an uncharged 20 µF capacitor C₃. (a) Calculate the p.d. across C₁ and C₂ after the first connection. (b) Calculate the charge on C₂ after the first connection. (c) Calculate the final charge on C₃, in µC. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '40 uC', 'µC', false, NULL, false, NULL, '(a) Q = 10 × 10⁻⁶ × 12 = 1.2 × 10⁻⁴ C shared over 30 µF: V = 1.2 × 10⁻⁴ ÷ 30 × 10⁻⁶ = 4.0 V. (b) Q₂ = 20 × 10⁻⁶ × 4.0 = 8.0 × 10⁻⁵ C. (c) C₂ and C₃ share 8.0 × 10⁻⁵ C over 40 µF: V = 8.0 × 10⁻⁵ ÷ 40 × 10⁻⁶ = 2.0 V, so Q₃ = 20 × 10⁻⁶ × 2.0 = 4.0 × 10⁻⁵ C. In µC: 4.0 × 10⁻⁵ × 10⁶ = 40. Mark scheme (5 marks). M1: charge conserved at each step. C1: V = 4.0 V. C1: Q₂. C1: second sharing. A1: Q₃ = 40 µC.', 5),
('891aafcb-39e4-5815-b7d9-745061213787', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1da133f6-6b3d-48ce-9d65-eff20177efd9', 'a-level', '23.3', '9702 coursebook 23.3 · Capacitors in parallel', 42, 42, 'A student connects increasing numbers n of nominally identical capacitors in parallel and measures the total capacitance: n = 1, 2, 3, 4 and C/µF = 4.6, 9.5, 14.0, 18.9. (a) Explain why a graph of C against n should be a straight line through the origin. (b) Calculate the gradient using the first and last readings. (c) State the mean capacitance of one capacitor, in µF. (d) Suggest why the individual readings do not lie exactly on the line. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '4.767', 'µF', false, NULL, false, ARRAY['4.767e-6']::text[], '(a) C_total = nC, so C ∝ n with gradient C. (b) Gradient = (18.9 − 4.6) ÷ (4 − 1) = 4.77 µF. (c) Mean capacitance = gradient = 4.77 µF. (d) The capacitors have a manufacturing tolerance (often ±10 %), and the meter and leads add small errors. Mark scheme (6 marks). B1: C_total = nC. C1: gradient. M1: gradient = C of one. B1: tolerance or stray capacitance. C1: value. A1: C = 4.77 µF.', 6),
('a811a756-922b-59ef-9833-0eacccf54d6f', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1da133f6-6b3d-48ce-9d65-eff20177efd9', 'a-level', '23.3', '9702 coursebook 23.3 · Capacitors in parallel', 43, 43, 'A power supply needs a smoothing capacitance of at least 10 000 µF that can work at 30 V. Only 2200 µF capacitors rated at 50 V are available. (a) Calculate the minimum number of capacitors needed and state how they must be connected. (b) Calculate the energy stored by this arrangement at 30 V. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '4.95', 'J', false, NULL, false, NULL, '(a) 10 000 ÷ 2200 = 4.55, so 5 capacitors in parallel (11 000 µF); parallel keeps each at 30 V, within its 50 V rating. (b) W = 0.5 × 5 × 2200 × 10⁻⁶ × 30² = 4.95 J. Mark scheme (5 marks). C1: 10 000 ÷ 2200. B1: 5 in parallel. B1: within voltage rating. C1: W = ½CV². A1: W = 4.95 J.', 5),
('31717b4c-3a94-58f3-8e8e-2535b0ad1798', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1da133f6-6b3d-48ce-9d65-eff20177efd9', 'a-level', '23.3', '9702 coursebook 23.3 · Capacitors in parallel', 44, 44, 'A 20 µF capacitor charged to 10 V and a 30 µF capacitor charged to 5.0 V are joined, positive plate to positive plate. (a) Calculate the total charge. (b) Calculate the final common p.d. (c) Calculate the energy lost, in mJ. (d) Calculate the final p.d. if instead the positive plate of each were joined to the negative plate of the other. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '7', 'V', false, NULL, false, NULL, '(a) Q = 20 × 10⁻⁶ × 10 + 30 × 10⁻⁶ × 5.0 = 3.5 × 10⁻⁴ C. (b) V = 3.5 × 10⁻⁴ ÷ 50 × 10⁻⁶ = 7.0 V. (c) Before: 0.5 × 20 × 10⁻⁶ × 10² + 0.5 × 30 × 10⁻⁶ × 5.0² = 0.00137 J; after: 0.5 × 50 × 10⁻⁶ × 7.0² = 0.00122 J; loss = 1.50 × 10⁻⁴ J, which is 0.150 mJ. (d) Charges partly cancel: V = (20 × 10 − 30 × 5.0) ÷ 50 = 1.0 V. Mark scheme (6 marks). C1: total charge. M1: V = Q_total/C_total. C1: energy before and after. C1: energy lost. B1: opposite connection gives 1.0 V. A1: V = 7.0 V.', 6),
('8e328b84-a9a5-563f-ad49-e8103d3f67c6', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1da133f6-6b3d-48ce-9d65-eff20177efd9', 'a-level', '23.3', '9702 coursebook 23.3 · Capacitors in parallel', 45, 45, '(a) Show that three capacitors in parallel have a total capacitance C = C₁ + C₂ + C₃. (b) Capacitors of 2.2 µF, 4.7 µF and 10 µF are connected in parallel across a 15 V supply. Calculate the total capacitance and the total charge, in µC. Give only the total charge.', NULL, 3, 'numeric'::answer_type, '253.5 uC', 'µC', false, NULL, false, NULL, '(a) Each has the same p.d. V; total charge Q = C₁V + C₂V + C₃V = (C₁ + C₂ + C₃)V, and C = Q/V. (b) C = 2.2 + 4.7 + 10 = 16.9 µF. Q = 16.9 × 10⁻⁶ × 15 = 2.535 × 10⁻⁴ C. In µC: 2.535 × 10⁻⁴ × 10⁶ = 254. Mark scheme (5 marks). M1: same p.d., charges add. B1: C = C₁ + C₂ + C₃. C1: total C. C1: Q = CV. A1: Q = 253 µC.', 5),
('4d9c399e-e347-53e6-b127-5218352999af', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1da133f6-6b3d-48ce-9d65-eff20177efd9', 'a-level', '23.3', '9702 coursebook 23.3 · Capacitors in parallel', 46, 46, 'A touch-screen sensor pad has a capacitance of 15 pF. A finger close to the pad adds 10 pF in parallel. The circuit charges the pad to 3.3 V and then discharges it 1000 times per second. (a) Calculate the charge on the pad with no finger present. (b) Calculate the extra charge per cycle when a finger is present. (c) Calculate the change in the average current, in nA. (d) Explain how the circuit detects a touch. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '33 nA', 'nA', false, NULL, false, NULL, '(a) Q = 15 × 10⁻¹² × 3.3 = 4.95 × 10⁻¹¹ C. (b) ΔQ = 10 × 10⁻¹² × 3.3 = 3.3 × 10⁻¹¹ C. (c) ΔI = ΔQ × 1000 = 3.3 × 10⁻¹¹ × 1000 = 3.3 × 10⁻⁸ A. In nA: 3.3 × 10⁻⁸ × 10⁹ = 33. (d) The extra parallel capacitance means more charge flows each cycle, so the average current rises; the circuit senses this rise. Mark scheme (6 marks). C1: Q = CV. M1: parallel capacitances add. C1: I = Q × frequency. C1: conversion to nA. B1: increase in current detected. A1: ΔI = 33 nA.', 6),
('ebc189c5-ea48-5386-bf9e-0c31689b70cd', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1da133f6-6b3d-48ce-9d65-eff20177efd9', 'a-level', '23.3', '9702 coursebook 23.3 · Capacitors in parallel', 47, 47, 'A 10 µF and a 40 µF capacitor are connected in parallel across a 20 V supply. (a) Calculate the energy stored in each. (b) Calculate the fraction of the total energy stored in the 10 µF capacitor. (c) State and explain how this fraction would change if the two capacitors were connected in series instead. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '0.2', NULL, false, NULL, false, NULL, '(a) W₁₀ = 0.5 × 10 × 10⁻⁶ × 20² = 2.0 × 10⁻³ J; W₄₀ = 0.5 × 40 × 10⁻⁶ × 20² = 8.0 × 10⁻³ J. (b) Fraction = 2.0 × 10⁻³ ÷ (2.0 × 10⁻³ + 8.0 × 10⁻³) = 0.20. (c) In series both carry the same charge, and W = Q²/2C, so the 10 µF capacitor would store four times as much as the 40 µF one: its fraction would rise to 0.80. Mark scheme (5 marks). C1: W = ½CV² for each. C1: fraction. M1: in series same Q. B1: W ∝ 1/C so fraction 0.80. A1: fraction = 0.20.', 5),
('994bca69-c5c9-5328-a92e-2a0240d14b8e', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1da133f6-6b3d-48ce-9d65-eff20177efd9', 'a-level', '23.3', '9702 coursebook 23.3 · Capacitors in parallel', 48, 48, 'A 100 µF capacitor charged to 20 V is connected across an identical uncharged capacitor, which is then disconnected and discharged. This is repeated. (a) Show that after n connections the p.d. on the first capacitor is 20/2ⁿ V. (b) Calculate the p.d. after 3 connections. (c) Find the smallest number of connections after which the energy stored is less than 1 % of its original value. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '2.5', 'V', false, NULL, false, NULL, '(a) Each connection shares the charge equally between two identical capacitors, halving Q and therefore V. (b) V = 20 ÷ 2³ = 2.5 V. (c) W ∝ V², so W falls by a factor of 4 each time. After 3 connections the energy is 1/64 of the original, about 1.6 %; after 4 it is 1/256, about 0.39 %, so 4 connections. Mark scheme (6 marks). M1: charge halves each time. C1: 20/2³. M1: W ∝ V², factor 4. C1: 1/64 > 1 %. A1: 4 connections. A1: V = 2.5 V.', 6),
('a87c01e5-e257-56e7-aec3-e70f0e966b96', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1da133f6-6b3d-48ce-9d65-eff20177efd9', 'a-level', '23.3', '9702 coursebook 23.3 · Capacitors in parallel', 49, 49, 'A pulsed laser is powered by 40 capacitors, each of 50 µF, connected in parallel and charged to 2.0 kV. (a) Calculate the total capacitance. (b) Calculate the energy stored. (c) The bank discharges in 1.0 ms. Calculate the average power, in MW. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '4000', 'J', false, NULL, false, NULL, '(a) C = 40 × 50 = 2000 µF. (b) W = 0.5 × 2000 × 10⁻⁶ × (2.0 × 10³)² = 4000 J. (c) P = 4000 ÷ 1.0 × 10⁻³ = 4.0 × 10⁶ W, which is 4.0 MW. Mark scheme (5 marks). C1: parallel capacitances add. C1: W = ½CV². C1: P = W/t. B1: MW conversion. A1: W = 4000 J.', 5),
('1761618b-5d38-5033-a154-c9b6d612c481', '34322ed1-8148-406d-97ee-947a4eca6b7f', '1da133f6-6b3d-48ce-9d65-eff20177efd9', 'a-level', '23.3', '9702 coursebook 23.3 · Capacitors in parallel', 50, 50, 'To measure an unknown capacitance C, a 470 µF capacitor is charged to 9.0 V and then connected across the unknown, uncharged capacitor. A voltmeter of very high resistance then reads 6.3 V. (a) Calculate the initial charge. (b) Calculate C, in µF. (c) Explain why the voltmeter must have a very high resistance. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '201.4', 'µF', false, NULL, false, ARRAY['2.014e-4']::text[], '(a) Q = 470 × 10⁻⁶ × 9.0 = 0.00423 C. (b) Charge conserved: (470 + C) × 6.3 = 470 × 9.0, so C = 470 × (9.0 − 6.3) ÷ 6.3 = 201 µF. (c) A low-resistance meter would let charge flow through it, discharging the capacitors and making the reading fall. Mark scheme (6 marks). C1: Q = CV. M1: charge conserved in parallel. C1: rearranged for C. C1: value. B1: meter must not discharge capacitors. A1: C = 201 µF.', 6)
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES
('1a666691-fe4f-5be8-beed-aec7971c6e55', 'f4c4cc8a-40f2-5292-99cf-a96ca36504bd', 'It equals the charge on the largest capacitor', 'A', false, 0),
('7d11641a-2437-5fae-bf5b-77aaa83dc254', 'f4c4cc8a-40f2-5292-99cf-a96ca36504bd', 'It equals the charge on each capacitor', 'B', false, 1),
('03e7c6cc-5410-598a-a022-da9336252d5f', 'f4c4cc8a-40f2-5292-99cf-a96ca36504bd', 'It is the sum of the individual charges', 'C', true, 2),
('312d421a-5444-5ce8-9ea5-4592402f3e3a', 'f4c4cc8a-40f2-5292-99cf-a96ca36504bd', 'It is the average of the individual charges', 'D', false, 3),
('7530f467-6456-5b4e-9b44-b84147329db5', '8b86df24-e1b5-5ea5-afe3-5b9e337b520f', 'C = C₁ + C₂ + C₃', 'A', true, 0),
('255e4e7a-89dd-5e3c-937d-6fd4aac722bb', '8b86df24-e1b5-5ea5-afe3-5b9e337b520f', '1/C = 1/C₁ + 1/C₂ + 1/C₃', 'B', false, 1),
('bd3782be-3e3d-5945-bd88-0b8178ebb6f1', '8b86df24-e1b5-5ea5-afe3-5b9e337b520f', 'C = C₁C₂C₃', 'C', false, 2),
('61c35d11-bc6e-51f7-bbb5-d2da47980f1e', '8b86df24-e1b5-5ea5-afe3-5b9e337b520f', 'C = (C₁ + C₂ + C₃)/3', 'D', false, 3),
('6eaffb57-7cab-5e82-b9a9-ff442627323b', '9bbd4ef4-f869-5225-833d-b95229f86fca', 'It decreases', 'A', false, 0),
('00f51ce3-0e57-5f0d-88e2-2af2341eba8c', '9bbd4ef4-f869-5225-833d-b95229f86fca', 'It stays the same', 'B', false, 1),
('f2c4dbb3-6381-53e4-ad76-b92d01f680e6', '9bbd4ef4-f869-5225-833d-b95229f86fca', 'It becomes zero', 'C', false, 2),
('adfc84a2-736a-56f2-b8c0-29b07170e568', '9bbd4ef4-f869-5225-833d-b95229f86fca', 'It increases', 'D', true, 3),
('ca438222-4c0c-5a65-9d56-cd29ca2d55ba', 'bde92a7f-1acb-5943-9956-96a3312c8279', 'The one with the smallest capacitance', 'A', false, 0),
('a3168eac-cd89-57f5-89f5-990d0696f8cc', 'bde92a7f-1acb-5943-9956-96a3312c8279', 'The one with the largest capacitance', 'B', true, 1),
('22a82091-3382-56ff-a54c-29c443fab04c', 'bde92a7f-1acb-5943-9956-96a3312c8279', 'They all store the same charge', 'C', false, 2),
('38ed3fe0-a173-513e-8dd6-81d86bf0f39a', 'bde92a7f-1acb-5943-9956-96a3312c8279', 'The one nearest the supply', 'D', false, 3),
('6e050490-3791-576a-9d05-9c4c76a69151', 'a3d4ed9d-484f-59fa-b005-3b799bd90626', 'It decreases', 'A', false, 0),
('48c79f9b-413f-547c-9a14-10d3e5adedab', 'a3d4ed9d-484f-59fa-b005-3b799bd90626', 'It stays the same', 'B', false, 1),
('f3fb5c80-e8bf-50de-9f54-0a329564e1a3', 'a3d4ed9d-484f-59fa-b005-3b799bd90626', 'It increases', 'C', true, 2),
('c25b8620-e0af-558d-81c8-33888e6f08cf', 'a3d4ed9d-484f-59fa-b005-3b799bd90626', 'It becomes equal to the new capacitor', 'D', false, 3),
('068fbd22-2caf-5056-9f31-6771f141a196', '90a790be-1535-5ab4-939f-a189b65fa0e8', '2C', 'A', true, 0),
('41895584-054a-52a9-95db-18702603f385', '90a790be-1535-5ab4-939f-a189b65fa0e8', 'C/2', 'B', false, 1),
('e0cf8653-7542-566c-aae4-670396aa03aa', '90a790be-1535-5ab4-939f-a189b65fa0e8', 'C', 'C', false, 2),
('00ea91f3-846a-52ab-88c1-126b991e83be', '90a790be-1535-5ab4-939f-a189b65fa0e8', 'C²', 'D', false, 3),
('35481277-ba01-50e7-a55d-fc7b4c0cd217', '189b4bd2-04f4-5953-a08b-b5cb3dc2dc95', 'It is less than the smallest capacitance', 'A', false, 0),
('70c6863e-f263-5216-a4ea-a680a8cc3382', '189b4bd2-04f4-5953-a08b-b5cb3dc2dc95', 'It equals the largest capacitance', 'B', false, 1),
('3b182d19-220e-527c-87a7-e2f138dc7629', '189b4bd2-04f4-5953-a08b-b5cb3dc2dc95', 'It equals the average capacitance', 'C', false, 2),
('17288efb-f23e-59f4-8b39-6028ce976b0a', '189b4bd2-04f4-5953-a08b-b5cb3dc2dc95', 'It is greater than the largest capacitance', 'D', true, 3),
('ab4c87ca-2bca-5b31-8f14-7699b4a9a729', '35abe8de-02cd-537e-9e37-4ae60bacb7ab', 'Doubling the separation of its plates', 'A', false, 0),
('1dc1d21e-c1c0-54cf-bcb7-088c20243def', '35abe8de-02cd-537e-9e37-4ae60bacb7ab', 'Doubling the area of its plates', 'B', true, 1),
('16c468f4-5208-50aa-8540-53730b44f43d', '35abe8de-02cd-537e-9e37-4ae60bacb7ab', 'Halving the area of its plates', 'C', false, 2),
('17474b1c-5bb7-5fc5-b916-79fa795f671b', '35abe8de-02cd-537e-9e37-4ae60bacb7ab', 'Removing its dielectric', 'D', false, 3),
('764547c9-ad9f-5b15-88a3-f8385fa7b241', 'fd82fb82-9cea-5f53-8e04-7e5325d4200c', 'The charge is the same on each capacitor, so the p.d.s add', 'A', false, 0),
('44f66aa9-4f34-5faa-8e4b-87252eb0f5c9', 'fd82fb82-9cea-5f53-8e04-7e5325d4200c', 'The current is the same in each capacitor', 'B', false, 1),
('e4b757d3-5628-598a-86b0-9198fd873c67', 'fd82fb82-9cea-5f53-8e04-7e5325d4200c', 'The p.d. is the same across each capacitor, so Q = Q₁ + Q₂ gives CV = C₁V + C₂V', 'C', true, 2),
('e4a8a97f-09e9-5605-9bd6-be8c3b259e00', 'fd82fb82-9cea-5f53-8e04-7e5325d4200c', 'The energy is the same in each capacitor', 'D', false, 3),
('8ab0bd03-2fc4-5b49-ac5d-474ead197ba0', 'db55ea20-d03a-5021-b39f-0e7de76d880d', 'Total charge is unchanged but total energy decreases', 'A', true, 0),
('19a97896-768f-52c8-a509-d189ef6ca1b6', 'db55ea20-d03a-5021-b39f-0e7de76d880d', 'Both are unchanged', 'B', false, 1),
('93be9231-59ad-57b4-89a2-2aa97e0da183', 'db55ea20-d03a-5021-b39f-0e7de76d880d', 'Total charge decreases but total energy is unchanged', 'C', false, 2),
('4c5b9d46-656f-53d1-a421-db6887f84ced', 'db55ea20-d03a-5021-b39f-0e7de76d880d', 'Both increase', 'D', false, 3),
('a6803825-4f6a-59f3-90be-d580fbe016e8', 'f81d4dfb-e4de-5cbe-9f0e-787c92c42fc7', 'About 1.0 µF', 'A', false, 0),
('077a7743-af37-5bcf-9f98-fae79ba17825', 'f81d4dfb-e4de-5cbe-9f0e-787c92c42fc7', 'About 50 µF', 'B', false, 1),
('b501a81d-54b7-51c4-a98b-1ade6568711b', 'f81d4dfb-e4de-5cbe-9f0e-787c92c42fc7', 'About 0.99 µF', 'C', false, 2),
('a93ab124-5970-54c6-92db-f89f6e87627e', 'f81d4dfb-e4de-5cbe-9f0e-787c92c42fc7', 'About 101 µF: the small capacitor makes little difference', 'D', true, 3),
('104f82da-c299-51a6-bca7-96db41b554b4', 'd91e574a-124d-5ff3-aa6d-63d8757495ee', 'p.d. V/2; total energy unchanged', 'A', false, 0),
('fdba44e1-32df-5188-a884-80c3a93586f1', 'd91e574a-124d-5ff3-aa6d-63d8757495ee', 'p.d. V/2; total energy half the original', 'B', true, 1),
('668c3a4f-72c9-5b8e-9f79-833fca3b2666', 'd91e574a-124d-5ff3-aa6d-63d8757495ee', 'p.d. V; total energy doubled', 'C', false, 2),
('3ac651b0-5b9f-5a9c-81db-2724a238c847', 'd91e574a-124d-5ff3-aa6d-63d8757495ee', 'p.d. V/2; total energy one quarter of the original', 'D', false, 3),
('f41d36d3-7bb6-5497-bbfa-fa75695b0179', 'db0aff4f-3261-5831-857e-0ed01ef6348e', '25 V', 'A', false, 0),
('27aab114-b245-54d0-905e-e4a33d1a6ce3', 'db0aff4f-3261-5831-857e-0ed01ef6348e', '41 V', 'B', false, 1),
('a1e0cd65-6054-5b38-ad5e-12f4a05fdc10', 'db0aff4f-3261-5831-857e-0ed01ef6348e', '16 V', 'C', true, 2),
('3a8ee200-0c83-5037-bf79-47c7a1d0a29f', 'db0aff4f-3261-5831-857e-0ed01ef6348e', '20.5 V', 'D', false, 3)
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points) VALUES
('2b3edb7c-d767-5cf5-aec3-f15f63158a14', '34322ed1-8148-406d-97ee-947a4eca6b7f', '418cd812-3eed-413c-87d7-8695a008d131', 'a-level', '23.4', '9702 coursebook 23.4 · Capacitors in series', 7, 7, 'Capacitors are connected in series to a battery. Which quantity is the same for every capacitor?', NULL, 1, 'multiple_choice'::answer_type, 'The charge on each capacitor', NULL, false, NULL, false, NULL, 'The battery moves charge Q onto the end plates; each inner pair of plates gets ±Q by electron transfer. Mark scheme (1 mark). B1: C (The charge on each capacitor).', 1),
('e2af951b-577f-5dc8-b677-0068adb10d9d', '34322ed1-8148-406d-97ee-947a4eca6b7f', '418cd812-3eed-413c-87d7-8695a008d131', 'a-level', '23.4', '9702 coursebook 23.4 · Capacitors in series', 8, 8, 'Which formula gives the total capacitance C of C₁ and C₂ in series?', NULL, 1, 'multiple_choice'::answer_type, '1/C = 1/C₁ + 1/C₂', NULL, false, NULL, false, NULL, 'The p.d.s add and the charge is common: V/Q = V₁/Q + V₂/Q. Mark scheme (1 mark). B1: A (1/C = 1/C₁ + 1/C₂).', 1),
('60ea1e04-ea9c-59b8-9275-6c78179c27c7', '34322ed1-8148-406d-97ee-947a4eca6b7f', '418cd812-3eed-413c-87d7-8695a008d131', 'a-level', '23.4', '9702 coursebook 23.4 · Capacitors in series', 9, 9, 'A 10 µF capacitor and a 15 µF capacitor are connected in series. Calculate the combined capacitance in µF.', NULL, 1, 'numeric'::answer_type, '6', 'µF', false, NULL, false, ARRAY['6e-6']::text[], '1/C = 1/10 + 1/15, so C = 10 × 15 ÷ (10 + 15) = 6.0 µF. Mark scheme (2 marks). C1: product over sum. A1: C = 6.0 µF.', 2),
('2dc084e8-a5c4-5009-b101-2df907672cee', '34322ed1-8148-406d-97ee-947a4eca6b7f', '418cd812-3eed-413c-87d7-8695a008d131', 'a-level', '23.4', '9702 coursebook 23.4 · Capacitors in series', 10, 10, 'Two 470 µF capacitors are connected in series. Calculate the combined capacitance in µF.', NULL, 1, 'numeric'::answer_type, '235', 'µF', false, NULL, false, ARRAY['2.35e-4']::text[], 'Two equal capacitors in series give half: C = 470 ÷ 2 = 235 µF. Mark scheme (2 marks). C1: 1/C = 2/470. A1: C = 235 µF.', 2),
('29882b99-eb17-5932-9181-c0d739e25ec7', '34322ed1-8148-406d-97ee-947a4eca6b7f', '418cd812-3eed-413c-87d7-8695a008d131', 'a-level', '23.4', '9702 coursebook 23.4 · Capacitors in series', 11, 11, 'How does the combined capacitance of capacitors in series compare with the smallest capacitance in the chain?', NULL, 1, 'multiple_choice'::answer_type, 'It is less than the smallest', NULL, false, NULL, false, NULL, 'Adding reciprocals makes 1/C larger than any single 1/Cₙ. Mark scheme (1 mark). B1: D (It is less than the smallest).', 1),
('91950d74-95d2-5841-8ba4-3c36f9dc25af', '34322ed1-8148-406d-97ee-947a4eca6b7f', '418cd812-3eed-413c-87d7-8695a008d131', 'a-level', '23.4', '9702 coursebook 23.4 · Capacitors in series', 12, 12, 'Two 2.0 µF capacitors in series are connected across a 12 V supply. Calculate the p.d. across each capacitor.', NULL, 1, 'numeric'::answer_type, '6', 'V', false, NULL, false, NULL, 'They are identical and carry the same charge, so the p.d. divides equally: 12 ÷ 2 = 6.0 V. Mark scheme (2 marks). C1: equal share for equal C. A1: V = 6.0 V.', 2),
('09b91411-bcf9-537e-a62f-186e0177b6c3', '34322ed1-8148-406d-97ee-947a4eca6b7f', '418cd812-3eed-413c-87d7-8695a008d131', 'a-level', '23.4', '9702 coursebook 23.4 · Capacitors in series', 13, 13, 'Two different capacitors in series are connected to a supply. Which capacitor has the larger p.d. across it?', NULL, 1, 'multiple_choice'::answer_type, 'The one with the smaller capacitance', NULL, false, NULL, false, NULL, 'Same Q, so V = Q/C is larger for smaller C. Mark scheme (1 mark). B1: B (The one with the smaller capacitance).', 1),
('a9b6fb94-704a-5ab0-8e57-bc80985d7e91', '34322ed1-8148-406d-97ee-947a4eca6b7f', '418cd812-3eed-413c-87d7-8695a008d131', 'a-level', '23.4', '9702 coursebook 23.4 · Capacitors in series', 14, 14, 'Calculate the combined capacitance of a 20 µF and a 5.0 µF capacitor in series, in µF.', NULL, 1, 'numeric'::answer_type, '4', 'µF', false, NULL, false, ARRAY['4e-6']::text[], 'C = 20 × 5.0 ÷ (20 + 5.0) = 4.0 µF. Mark scheme (2 marks). C1: product over sum. A1: C = 4.0 µF.', 2),
('8ce5e4d0-ebb3-5784-8829-a51ae8f5274d', '34322ed1-8148-406d-97ee-947a4eca6b7f', '418cd812-3eed-413c-87d7-8695a008d131', 'a-level', '23.4', '9702 coursebook 23.4 · Capacitors in series', 15, 15, 'Several capacitors in series behave as a single 3.0 µF capacitor. When 10 V is applied across the chain, what charge sits on each capacitor, in µC?', NULL, 1, 'numeric'::answer_type, '30 uC', 'µC', false, NULL, false, NULL, 'Q = CV = 3.0 × 10⁻⁶ × 10 = 3.0 × 10⁻⁵ C. In µC: 3.0 × 10⁻⁵ × 10⁶ = 30. Mark scheme (2 marks). C1: Q = C_total V. A1: Q = 30 µC.', 2),
('f1d17ebe-fc5a-5f8c-8244-70e25a95e71c', '34322ed1-8148-406d-97ee-947a4eca6b7f', '418cd812-3eed-413c-87d7-8695a008d131', 'a-level', '23.4', '9702 coursebook 23.4 · Capacitors in series', 16, 16, 'For capacitors in series across a supply, how are the individual p.d.s related to the supply p.d.?', NULL, 1, 'multiple_choice'::answer_type, 'They add up to the supply p.d.', NULL, false, NULL, false, NULL, 'By energy conservation (Kirchhoff''s second law), the p.d.s around a series chain sum to the e.m.f. Mark scheme (1 mark). B1: C (They add up to the supply p.d.).', 1),
('8c4e8888-ee0c-5077-8c63-dfbe15f635d0', '34322ed1-8148-406d-97ee-947a4eca6b7f', '418cd812-3eed-413c-87d7-8695a008d131', 'a-level', '23.4', '9702 coursebook 23.4 · Capacitors in series', 17, 17, 'A chain of four identical 100 µF capacitors is wired end to end. What single capacitance, in µF, could replace the chain?', NULL, 1, 'numeric'::answer_type, '25', 'µF', false, NULL, false, ARRAY['2.5e-5']::text[], '1/C = 4/100, so C = 100 ÷ 4 = 25 µF. Mark scheme (2 marks). C1: n equal capacitors give C/n. A1: C = 25 µF.', 2),
('c3484878-12dc-5623-97e9-9af6daaa0d49', '34322ed1-8148-406d-97ee-947a4eca6b7f', '418cd812-3eed-413c-87d7-8695a008d131', 'a-level', '23.4', '9702 coursebook 23.4 · Capacitors in series', 18, 18, 'Why might capacitors be connected in series in a high-voltage circuit?', NULL, 1, 'multiple_choice'::answer_type, 'So that the supply p.d. is shared, and no single capacitor exceeds its voltage rating', NULL, false, NULL, false, NULL, 'In series each capacitor has only part of the total p.d. Mark scheme (1 mark). B1: A (So that the supply p.d. is shared, and no single capacitor exceeds its voltage rating).', 1),
('8e204f38-a970-5b77-9858-f551644c6f49', '34322ed1-8148-406d-97ee-947a4eca6b7f', '418cd812-3eed-413c-87d7-8695a008d131', 'a-level', '23.4', '9702 coursebook 23.4 · Capacitors in series', 19, 19, 'Two identical capacitors in series have a combined capacitance of 50 µF. What is the capacitance of each, in µF?', NULL, 1, 'numeric'::answer_type, '100', 'µF', false, NULL, false, ARRAY['1e-4']::text[], 'C_series = C/2, so C = 2 × 50 = 100 µF. Mark scheme (1 mark). A1: C = 100 µF.', 1),
('4fcda3ef-8080-5f21-a242-27b6aa22edf5', '34322ed1-8148-406d-97ee-947a4eca6b7f', '418cd812-3eed-413c-87d7-8695a008d131', 'a-level', '23.4', '9702 coursebook 23.4 · Capacitors in series', 20, 20, 'Three 1.0 µF capacitors are connected in series across a 9.0 V supply. Calculate the p.d. across each.', NULL, 1, 'numeric'::answer_type, '3', 'V', false, NULL, false, NULL, 'Identical capacitors share the p.d. equally: 9.0 ÷ 3 = 3.0 V. Mark scheme (2 marks). C1: equal share. A1: V = 3.0 V.', 2),
('eac2789a-ea32-5275-9d5c-e5f368511163', '34322ed1-8148-406d-97ee-947a4eca6b7f', '418cd812-3eed-413c-87d7-8695a008d131', 'a-level', '23.4', '9702 coursebook 23.4 · Capacitors in series', 21, 21, 'How do the inner plates of two capacitors in series become charged, even though they are not connected to the supply?', NULL, 1, 'multiple_choice'::answer_type, 'Electrons move along the wire between them, leaving one plate positive and the other negative', NULL, false, NULL, false, NULL, 'The charge on the outer plates attracts or repels electrons in the isolated middle section. Mark scheme (1 mark). B1: D (Electrons move along the wire between them, leaving one plate positive and the other negative).', 1),
('5d20b3c5-0fc5-5940-9da5-3a45cade9794', '34322ed1-8148-406d-97ee-947a4eca6b7f', '418cd812-3eed-413c-87d7-8695a008d131', 'a-level', '23.4', '9702 coursebook 23.4 · Capacitors in series', 22, 22, 'Find the effective capacitance, in µF, when a 3.3 µF capacitor is placed in series with a 6.8 µF one.', NULL, 1, 'numeric'::answer_type, '2.222', 'µF', false, NULL, false, ARRAY['2.222e-6']::text[], 'C = 6.8 × 3.3 ÷ (6.8 + 3.3) = 2.22 µF. Mark scheme (2 marks). C1: product over sum. A1: C = 2.22 µF.', 2),
('e2e8c348-0efc-52fa-82c7-a24cc0dcc782', '34322ed1-8148-406d-97ee-947a4eca6b7f', '418cd812-3eed-413c-87d7-8695a008d131', 'a-level', '23.4', '9702 coursebook 23.4 · Capacitors in series', 23, 23, 'A third capacitor is added in series to two capacitors already in series. What happens to the total capacitance?', NULL, 1, 'multiple_choice'::answer_type, 'It decreases', NULL, false, NULL, false, NULL, 'Another positive term is added to 1/C, so C falls. Mark scheme (1 mark). B1: B (It decreases).', 1),
('8cac61f8-7289-5131-952f-c7468a43a085', '34322ed1-8148-406d-97ee-947a4eca6b7f', '418cd812-3eed-413c-87d7-8695a008d131', 'a-level', '23.4', '9702 coursebook 23.4 · Capacitors in series', 24, 24, 'A 4.0 µF and a 6.0 µF capacitor are connected in series across a 20 V supply. Calculate the charge on each capacitor, in µC.', NULL, 2, 'numeric'::answer_type, '48 uC', 'µC', false, NULL, false, NULL, 'C = 4.0 × 6.0 ÷ (4.0 + 6.0) = 2.4 µF. Q = 2.4 × 10⁻⁶ × 20 = 4.8 × 10⁻⁵ C. In µC: 4.8 × 10⁻⁵ × 10⁶ = 48. Mark scheme (3 marks). C1: series C. C1: Q = CV. A1: Q = 48 µC.', 3),
('50e18c84-ce80-5c5c-97e6-bc15dfe975e7', '34322ed1-8148-406d-97ee-947a4eca6b7f', '418cd812-3eed-413c-87d7-8695a008d131', 'a-level', '23.4', '9702 coursebook 23.4 · Capacitors in series', 25, 25, 'A 4.0 µF and a 6.0 µF capacitor in series across 20 V each carry 48 µC. Calculate the p.d. across the 4.0 µF capacitor.', NULL, 2, 'numeric'::answer_type, '12', 'V', false, NULL, false, NULL, 'V = Q/C = 48 × 10⁻⁶ ÷ 4.0 × 10⁻⁶ = 12 V. Mark scheme (3 marks). C1: same Q on each. C1: V = Q/C. A1: V = 12 V.', 3),
('9e7be1b7-bf14-59f1-92bf-ea65c5ee96ea', '34322ed1-8148-406d-97ee-947a4eca6b7f', '418cd812-3eed-413c-87d7-8695a008d131', 'a-level', '23.4', '9702 coursebook 23.4 · Capacitors in series', 26, 26, 'Capacitors of 2.0 µF, 3.0 µF and 6.0 µF are connected in series across a 12 V supply. Calculate the p.d. across the 2.0 µF capacitor.', NULL, 2, 'numeric'::answer_type, '6', 'V', false, NULL, false, NULL, '1/C = 1/2.0 + 1/3.0 + 1/6.0 = 1.0, so C = 1.0 µF. Q = 1.0 × 10⁻⁶ × 12 = 1.2 × 10⁻⁵ C. V = 1.2 × 10⁻⁵ ÷ 2.0 × 10⁻⁶ = 6.0 V. Mark scheme (4 marks). C1: series C. C1: Q = CV. C1: V = Q/C. A1: V = 6.0 V.', 4),
('04c8e439-0bbe-5799-9be7-f4b9acc1a5bc', '34322ed1-8148-406d-97ee-947a4eca6b7f', '418cd812-3eed-413c-87d7-8695a008d131', 'a-level', '23.4', '9702 coursebook 23.4 · Capacitors in series', 27, 27, 'A 1.0 µF and a 3.0 µF capacitor are connected in series across a supply. What is (p.d. across 1.0 µF) ÷ (p.d. across 3.0 µF)?', NULL, 2, 'multiple_choice'::answer_type, '3', NULL, false, NULL, false, NULL, 'Same Q, so V ∝ 1/C: the smaller capacitor takes three times the p.d. Mark scheme (3 marks). C1: same Q. C1: V ∝ 1/C. A1: C (3).', 3),
('9286f8dd-2a9f-52e1-8d63-be9e5c0cb930', '34322ed1-8148-406d-97ee-947a4eca6b7f', '418cd812-3eed-413c-87d7-8695a008d131', 'a-level', '23.4', '9702 coursebook 23.4 · Capacitors in series', 28, 28, 'Two 100 µF capacitors in series are charged to a total p.d. of 50 V. Calculate the total energy stored, in mJ.', NULL, 2, 'numeric'::answer_type, '62.5 mJ', 'mJ', false, NULL, false, NULL, 'C = 100 ÷ 2 = 50 µF. W = 0.5 × 50 × 10⁻⁶ × 50² = 0.0625 J. In mJ: 0.0625 × 1000 = 62.5. Mark scheme (3 marks). C1: series C. C1: W = ½CV². A1: W = 62.5 mJ.', 3),
('40204b28-14de-5ab0-ad9e-a942fa7868e0', '34322ed1-8148-406d-97ee-947a4eca6b7f', '418cd812-3eed-413c-87d7-8695a008d131', 'a-level', '23.4', '9702 coursebook 23.4 · Capacitors in series', 29, 29, 'A 12 µF capacitor is connected in series with an unknown capacitor, giving a combined capacitance of 4.0 µF. Calculate the unknown capacitance, in µF.', NULL, 2, 'numeric'::answer_type, '6', 'µF', false, NULL, false, ARRAY['6e-6']::text[], '1/C_x = 1/4.0 − 1/12 = 1/6.0, so C_x = 1 ÷ (1/4.0 − 1/12) = 6.0 µF. Mark scheme (3 marks). M1: 1/C_x = 1/C − 1/C₁. C1: value. A1: C = 6.0 µF.', 3),
('0629633c-c6a1-53ab-aed1-eacbb57a2895', '34322ed1-8148-406d-97ee-947a4eca6b7f', '418cd812-3eed-413c-87d7-8695a008d131', 'a-level', '23.4', '9702 coursebook 23.4 · Capacitors in series', 30, 30, 'Two 100 µF capacitors, each rated at 16 V, are connected in series. Which row gives the combination''s capacitance and maximum safe p.d.?', NULL, 2, 'multiple_choice'::answer_type, '50 µF and 32 V', NULL, false, NULL, false, NULL, 'Series halves C; each takes half the p.d., so the pair can take 2 × 16 V. Mark scheme (4 marks). C1: series C = 50 µF. C1: p.d. shared equally. C1: 32 V. A1: A (50 µF and 32 V).', 4),
('02bbcc3c-9512-5a90-98d0-da2586367bc4', '34322ed1-8148-406d-97ee-947a4eca6b7f', '418cd812-3eed-413c-87d7-8695a008d131', 'a-level', '23.4', '9702 coursebook 23.4 · Capacitors in series', 31, 31, 'A 2.0 µF and an 8.0 µF capacitor are in series across a 10 V supply. Calculate the energy stored in the 2.0 µF capacitor, in µJ.', NULL, 2, 'numeric'::answer_type, '64 uJ', 'µJ', false, NULL, false, NULL, 'C = 2.0 × 8.0 ÷ 10 = 1.6 µF. Q = 1.6 × 10⁻⁶ × 10 = 1.6 × 10⁻⁵ C. W = Q²/2C = (1.6 × 10⁻⁵)² ÷ (2 × 2.0 × 10⁻⁶) = 6.40 × 10⁻⁵ J. In µJ: 6.40 × 10⁻⁵ × 10⁶ = 64.0. Mark scheme (3 marks). C1: series C and Q. C1: W = Q²/2C. A1: W = 64.0 µJ.', 3),
('efcb8d99-a9e3-5e66-961f-e6aa48f3d3b6', '34322ed1-8148-406d-97ee-947a4eca6b7f', '418cd812-3eed-413c-87d7-8695a008d131', 'a-level', '23.4', '9702 coursebook 23.4 · Capacitors in series', 32, 32, 'A 22 µF and a 47 µF capacitor in series are connected across 9.0 V. Calculate the charge on each, in µC.', NULL, 2, 'numeric'::answer_type, '134.9 uC', 'µC', false, NULL, false, NULL, 'C = 22 × 47 ÷ (22 + 47) = 15.0 µF. Q = 14.99 × 9.0 = 135 µC. Mark scheme (3 marks). C1: series C. C1: Q = CV. A1: Q = 135 µC.', 3),
('9bafd23e-728f-57f0-9d8c-0337c8a168fe', '34322ed1-8148-406d-97ee-947a4eca6b7f', '418cd812-3eed-413c-87d7-8695a008d131', 'a-level', '23.4', '9702 coursebook 23.4 · Capacitors in series', 33, 33, 'In a series pair, one capacitor is replaced by one of very much larger capacitance. What does the combined capacitance approach?', NULL, 2, 'multiple_choice'::answer_type, 'The capacitance of the other (smaller) capacitor', NULL, false, NULL, false, NULL, '1/C = 1/C₁ + 1/C₂ → 1/C₁ as C₂ → ∞. Mark scheme (3 marks). C1: 1/C₂ → 0. C1: C → C₁. A1: D (The capacitance of the other (smaller) capacitor).', 3),
('f8900d6d-c3c2-5b84-957e-afc659a6fbfd', '34322ed1-8148-406d-97ee-947a4eca6b7f', '418cd812-3eed-413c-87d7-8695a008d131', 'a-level', '23.4', '9702 coursebook 23.4 · Capacitors in series', 34, 34, 'Three identical 0.30 µF capacitors, each rated at 2.0 kV, are connected in series across a 5.0 kV supply. Calculate the charge on each capacitor, in mC.', NULL, 2, 'numeric'::answer_type, '0.5 mC', 'mC', false, NULL, false, NULL, 'C = 0.30 ÷ 3 = 0.10 µF. Q = 0.10 × 10⁻⁶ × 5.0 × 10³ = 5.0 × 10⁻⁴ C. In mC: 5.0 × 10⁻⁴ × 1000 = 0.50. Each has 5.0 ÷ 3 = 1.67 kV, within its rating. Mark scheme (4 marks). C1: series C. C1: Q = CV. C1: conversion to mC. A1: Q = 0.50 mC.', 4),
('14ac0f1a-860e-53b9-b21f-4cfa70c9869c', '34322ed1-8148-406d-97ee-947a4eca6b7f', '418cd812-3eed-413c-87d7-8695a008d131', 'a-level', '23.4', '9702 coursebook 23.4 · Capacitors in series', 35, 35, 'How many 10 µF capacitors must be connected in series to give a combined capacitance of 2.5 µF?', NULL, 2, 'numeric'::answer_type, '4', NULL, false, NULL, false, NULL, 'n equal capacitors in series give C/n, so n = 10 ÷ 2.5 = 4. Mark scheme (3 marks). C1: C_total = C/n. C1: rearranged. A1: n = 4.', 3),
('81673610-04d2-5353-a76a-40176017ca4e', '34322ed1-8148-406d-97ee-947a4eca6b7f', '418cd812-3eed-413c-87d7-8695a008d131', 'a-level', '23.4', '9702 coursebook 23.4 · Capacitors in series', 36, 36, 'Why do all capacitors in a series chain carry the same charge?', NULL, 2, 'multiple_choice'::answer_type, 'Each isolated section between capacitors is neutral overall, so it gains +Q on one plate exactly as it loses −Q from the other', NULL, false, NULL, false, NULL, 'Charge conservation in each isolated conductor between capacitors gives equal and opposite charges. Mark scheme (3 marks). C1: isolated sections. C1: charge conservation. A1: B (Each isolated section between capacitors is neutral overall, so it gains +Q on one plate exactly as it loses −Q from the other).', 3),
('f31d8ed7-e7a4-5a6b-be93-6f60ec28fdd6', '34322ed1-8148-406d-97ee-947a4eca6b7f', '418cd812-3eed-413c-87d7-8695a008d131', 'a-level', '23.4', '9702 coursebook 23.4 · Capacitors in series', 37, 37, 'A 0.10 µF capacitor is connected in series with a 100 µF capacitor. Calculate the combined capacitance, in µF.', NULL, 2, 'numeric'::answer_type, '0.0999', 'µF', false, NULL, false, ARRAY['9.99e-8']::text[], 'C = 0.10 × 100 ÷ (0.10 + 100) = 0.0999 µF: almost exactly the smaller value. Mark scheme (3 marks). C1: product over sum. C1: dominated by the smaller C. A1: C = 0.0999 µF.', 3),
('79307f8c-e3a0-5edf-b77a-48a3eaf37a54', '34322ed1-8148-406d-97ee-947a4eca6b7f', '418cd812-3eed-413c-87d7-8695a008d131', 'a-level', '23.4', '9702 coursebook 23.4 · Capacitors in series', 38, 38, 'A 10 µF and a 40 µF capacitor are connected in series across 25 V. Calculate the p.d. across the 10 µF capacitor.', NULL, 2, 'numeric'::answer_type, '20', 'V', false, NULL, false, NULL, 'Same Q, so V ∝ 1/C and the p.d.s are in the ratio 40 : 10. V₁₀ = 25 × 40 ÷ (10 + 40) = 20 V. Mark scheme (4 marks). C1: same Q. M1: V ∝ 1/C. C1: share of 25 V. A1: V = 20 V.', 4),
('2b902ad4-28ce-5d93-a8ba-b5f0a05837d6', '34322ed1-8148-406d-97ee-947a4eca6b7f', '418cd812-3eed-413c-87d7-8695a008d131', 'a-level', '23.4', '9702 coursebook 23.4 · Capacitors in series', 39, 39, 'Two identical capacitors are connected first in parallel and then in series. What is (capacitance in parallel) ÷ (capacitance in series)?', NULL, 2, 'multiple_choice'::answer_type, '4', NULL, false, NULL, false, NULL, 'Parallel: 2C. Series: C/2. Ratio = 4. Mark scheme (3 marks). C1: parallel 2C. C1: series C/2. A1: C (4).', 3),
('01cc78e3-748c-5921-9e2c-ba2bf814689a', '34322ed1-8148-406d-97ee-947a4eca6b7f', '418cd812-3eed-413c-87d7-8695a008d131', 'a-level', '23.4', '9702 coursebook 23.4 · Capacitors in series', 40, 40, 'A 3.3 µF and a 6.8 µF capacitor in series are charged by a 15 V supply. Calculate the total energy stored, in mJ.', NULL, 2, 'numeric'::answer_type, '0.25 mJ', 'mJ', false, NULL, false, NULL, 'C = 3.3 × 6.8 ÷ 10.1 = 2.22 µF. W = 0.5 × 2.222 × 10⁻⁶ × 15² = 2.50 × 10⁻⁴ J. In mJ: 2.500 × 10⁻⁴ × 1000 = 0.250. Mark scheme (3 marks). C1: series C. C1: W = ½CV². A1: W = 0.250 mJ.', 3),
('bb1e6c84-31e8-5f23-9d3a-3783618e8fd0', '34322ed1-8148-406d-97ee-947a4eca6b7f', '418cd812-3eed-413c-87d7-8695a008d131', 'a-level', '23.4', '9702 coursebook 23.4 · Capacitors in series', 41, 41, '(a) Show that three capacitors in series have a combined capacitance given by 1/C = 1/C₁ + 1/C₂ + 1/C₃. (b) Capacitors of 4.7 µF, 10 µF and 22 µF are connected in series across 30 V. Calculate the combined capacitance. (c) Calculate the charge on each capacitor. (d) Calculate the p.d. across the 4.7 µF capacitor. Give only the answer to (d).', NULL, 3, 'numeric'::answer_type, '17.82', 'V', false, NULL, false, NULL, '(a) Each capacitor carries Q and V = V₁ + V₂ + V₃, so Q/C = Q/C₁ + Q/C₂ + Q/C₃; dividing by Q gives the result. (b) 1/C = 1/4.7 + 1/10 + 1/22 = 0.3582, so C = 2.79 µF. (c) Q = 2.792 × 30 = 83.7 µC. (d) V = 83.75 ÷ 4.7 = 17.8 V. Mark scheme (6 marks). M1: same Q, p.d.s add. B1: reciprocal rule derived. C1: series C. C1: Q = CV. C1: V = Q/C. A1: V = 17.8 V.', 6),
('ebe0d6ba-2339-5078-b1ee-8b33ce39820d', '34322ed1-8148-406d-97ee-947a4eca6b7f', '418cd812-3eed-413c-87d7-8695a008d131', 'a-level', '23.4', '9702 coursebook 23.4 · Capacitors in series', 42, 42, 'A capacitive voltage divider uses a 100 pF capacitor in series with a 900 pF capacitor across a 1000 V source. (a) Explain why the charge on each capacitor is the same. (b) Calculate the combined capacitance. (c) Calculate the p.d. across the 900 pF capacitor. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '100', 'V', false, NULL, false, NULL, '(a) The middle conductor is isolated, so it gains equal and opposite charges. (b) C = 100 × 900 ÷ 1000 = 90 pF. (c) Q = 90 × 10⁻¹² × 1000 = 9.0 × 10⁻⁸ C. V = 9.0 × 10⁻⁸ ÷ 900 × 10⁻¹² = 100 V. Mark scheme (5 marks). B1: isolated middle conductor. C1: series C. C1: Q = CV. C1: V = Q/C. A1: V = 100 V.', 5),
('71d491fa-c31f-5f8c-acdd-bb55938e7006', '34322ed1-8148-406d-97ee-947a4eca6b7f', '418cd812-3eed-413c-87d7-8695a008d131', 'a-level', '23.4', '9702 coursebook 23.4 · Capacitors in series', 43, 43, 'A 2.0 µF capacitor and a 3.0 µF capacitor are each rated at 50 V. They are connected in series. (a) Explain which capacitor has the larger p.d. across it. (b) Find the fraction of the supply p.d. across the 2.0 µF capacitor. (c) Calculate the largest supply p.d. that can be used without exceeding either rating. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '83.33', 'V', false, NULL, false, NULL, '(a) The 2.0 µF capacitor: same charge, so V = Q/C is larger for smaller C. (b) V ∝ 1/C, so the fraction = 3.0 ÷ (2.0 + 3.0) = 0.60. (c) The 2.0 µF capacitor reaches 50 V first: V_supply = 50 ÷ 0.60 = 83.3 V. Mark scheme (6 marks). B1: smaller C has larger V. M1: V ∝ 1/C. C1: fraction 0.60. C1: limit set by the 2.0 µF capacitor. C1: substitution. A1: V = 83.3 V.', 6),
('e394eb68-e0e4-5502-9084-80c811ff29cb', '34322ed1-8148-406d-97ee-947a4eca6b7f', '418cd812-3eed-413c-87d7-8695a008d131', 'a-level', '23.4', '9702 coursebook 23.4 · Capacitors in series', 44, 44, 'A 4.0 µF and a 12 µF capacitor are connected in series across a 16 V supply. (a) Calculate the combined capacitance. (b) Calculate the charge on each. (c) Calculate the energy stored in each capacitor. (d) Show that the total equals the energy stored in the combined capacitance. Give only the energy in the 4.0 µF capacitor, in mJ.', NULL, 3, 'numeric'::answer_type, '0.288 mJ', 'mJ', false, NULL, false, NULL, '(a) C = 4.0 × 12 ÷ 16 = 3.0 µF. (b) Q = 3.0 × 10⁻⁶ × 16 = 4.8 × 10⁻⁵ C. (c) W₄ = (4.8 × 10⁻⁵)² ÷ (2 × 4.0 × 10⁻⁶) = 2.88 × 10⁻⁴ J. In mJ: 2.88 × 10⁻⁴ × 1000 = 0.288. W₁₂ = (4.8 × 10⁻⁵)² ÷ (2 × 12 × 10⁻⁶) = 9.60 × 10⁻⁵ J. (d) Total = 3.84 × 10⁻⁴ J, and 0.5 × 3.0 × 10⁻⁶ × 16² = 3.84 × 10⁻⁴ J, the same. Mark scheme (6 marks). C1: series C. C1: Q = CV. M1: W = Q²/2C for each. C1: values. B1: totals agree. A1: W = 0.288 mJ.', 6),
('2d3436be-229f-5ab3-a989-b001a82e7f90', '34322ed1-8148-406d-97ee-947a4eca6b7f', '418cd812-3eed-413c-87d7-8695a008d131', 'a-level', '23.4', '9702 coursebook 23.4 · Capacitors in series', 45, 45, 'A 2.0 µF and a 6.0 µF capacitor are connected in series across a 12 V supply. They are then disconnected from the supply and from each other, and reconnected in parallel, positive plate to positive plate. (a) Calculate the charge on each capacitor while in series. (b) Calculate the total charge after reconnection. (c) Calculate the final p.d. across the parallel pair. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '4.5', 'V', false, NULL, false, NULL, '(a) C = 2.0 × 6.0 ÷ 8.0 = 1.5 µF; Q = 1.5 × 10⁻⁶ × 12 = 1.8 × 10⁻⁵ C on each. (b) Positive plates joined: total Q = 2 × 1.8 × 10⁻⁵ = 3.6 × 10⁻⁵ C. (c) In parallel C = 8.0 µF, so V = 3.6 × 10⁻⁵ ÷ 8.0 × 10⁻⁶ = 4.5 V. Mark scheme (6 marks). C1: series C. C1: same Q on each. M1: charges add when like plates joined. C1: parallel C. C1: V = Q/C. A1: V = 4.5 V.', 6),
('c118b995-76a0-51dd-a091-18a7df645f3e', '34322ed1-8148-406d-97ee-947a4eca6b7f', '418cd812-3eed-413c-87d7-8695a008d131', 'a-level', '23.4', '9702 coursebook 23.4 · Capacitors in series', 46, 46, 'Three 6.0 µF capacitors are connected in series across an 18 V supply. One of them breaks down and becomes a short circuit. (a) Calculate the p.d. across each capacitor before the fault. (b) Calculate the combined capacitance after the fault. (c) Calculate the p.d. across each of the remaining capacitors. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '9', 'V', false, NULL, false, NULL, '(a) Identical, so 18 ÷ 3 = 6.0 V each. (b) Two 6.0 µF in series: C = 6.0 ÷ 2 = 3.0 µF. (c) The 18 V is now shared by two: 18 ÷ 2 = 9.0 V each, which may exceed their rating. Mark scheme (5 marks). C1: equal share before. C1: series C of two. M1: supply p.d. shared by two. B1: risk of further breakdown. A1: V = 9.0 V.', 5),
('82a531b7-019a-51fd-b348-40b5cefe5672', '34322ed1-8148-406d-97ee-947a4eca6b7f', '418cd812-3eed-413c-87d7-8695a008d131', 'a-level', '23.4', '9702 coursebook 23.4 · Capacitors in series', 47, 47, 'A student connects n identical capacitors in series and measures the combined capacitance C. Values of 1/C are: n = 1, 2, 3, 4 and (1/C)/µF⁻¹ = 0.213, 0.426, 0.638, 0.851. (a) Explain why a graph of 1/C against n is a straight line through the origin. (b) Calculate the gradient using the first and last readings. (c) Calculate the capacitance of one capacitor, in µF. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '4.702', 'µF', false, NULL, false, ARRAY['4.702e-6']::text[], '(a) 1/C = n/C₁, so 1/C ∝ n with gradient 1/C₁. (b) Gradient = (0.851 − 0.213) ÷ (4 − 1) = 0.213 µF⁻¹. (c) C₁ = 1 ÷ 0.2127 = 4.70 µF. Mark scheme (6 marks). M1: 1/C = n/C₁. B1: straight line through origin. C1: gradient. C1: C₁ = 1/gradient. C1: value. A1: C = 4.70 µF.', 6),
('6576622c-a52b-5106-b4c1-f1b581561ddd', '34322ed1-8148-406d-97ee-947a4eca6b7f', '418cd812-3eed-413c-87d7-8695a008d131', 'a-level', '23.4', '9702 coursebook 23.4 · Capacitors in series', 48, 48, 'An unknown capacitor is connected in series with a 10 µF capacitor across a 12 V supply. A high-resistance voltmeter shows 8.0 V across the 10 µF capacitor. (a) Calculate the charge on the 10 µF capacitor. (b) State the p.d. across the unknown capacitor. (c) Calculate the unknown capacitance, in µF. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '20', 'µF', false, NULL, false, ARRAY['2e-5']::text[], '(a) Q = 10 × 10⁻⁶ × 8.0 = 8.0 × 10⁻⁵ C. (b) 12 − 8.0 = 4.0 V. (c) Same charge in series: C = 8.0 × 10⁻⁵ ÷ 4.0 = 2.0 × 10⁻⁵ F. In µF: 2.0 × 10⁻⁵ × 10⁶ = 20. Mark scheme (5 marks). C1: Q = CV. C1: p.d.s add to 12 V. M1: same Q. C1: C = Q/V. A1: C = 20 µF.', 5),
('8d0c19e2-5974-5efe-94f8-7ea6735b7d22', '34322ed1-8148-406d-97ee-947a4eca6b7f', '418cd812-3eed-413c-87d7-8695a008d131', 'a-level', '23.4', '9702 coursebook 23.4 · Capacitors in series', 49, 49, 'Three identical 3.3 µF capacitors are connected in series across a 9.9 V supply. (a) Calculate the combined capacitance. (b) Calculate the charge on each capacitor. (c) Calculate the number of electrons that flowed onto the plate connected to the negative terminal. (d) Explain why the inner plates are charged although they are not connected to the supply. Give only the answer to (c). Take e = 1.60 × 10⁻¹⁹ C.', NULL, 3, 'numeric'::answer_type, '6.806e13', NULL, false, NULL, false, NULL, '(a) C = 3.3 ÷ 3 = 1.1 µF. (b) Q = 1.1 × 10⁻⁶ × 9.9 = 1.09 × 10⁻⁵ C. (c) N = 1.089 × 10⁻⁵ ÷ 1.60 × 10⁻¹⁹ = 6.81 × 10¹³. (d) The charges on the outer plates attract or repel electrons in each isolated middle conductor, so its two plates gain equal and opposite charges. Mark scheme (6 marks). C1: series C. C1: Q = CV. C1: N = Q/e. B1: induced charge separation. B1: isolated conductor stays neutral overall. A1: N = 6.81 × 10¹³.', 6),
('27e0cc63-8068-579f-bdfd-0a3feb53cb16', '34322ed1-8148-406d-97ee-947a4eca6b7f', '418cd812-3eed-413c-87d7-8695a008d131', 'a-level', '23.4', '9702 coursebook 23.4 · Capacitors in series', 50, 50, 'Two capacitors give a combined capacitance of 2.4 µF in series and 10 µF in parallel. (a) Write two equations for the capacitances C₁ and C₂. (b) Show that C₁C₂ = 24 µF². (c) Find the larger capacitance, in µF. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '6', 'µF', false, NULL, false, ARRAY['6e-6']::text[], '(a) C₁ + C₂ = 10 and C₁C₂/(C₁ + C₂) = 2.4. (b) C₁C₂ = 2.4 × 10 = 24. (c) C₁ and C₂ are the roots of C² − 10C + 24 = 0: C = (10 + √(10² − 4 × 24)) ÷ 2 = 6.0 µF; the other is 4.0 µF. Mark scheme (5 marks). B1: both equations. M1: product = 2.4 × sum. C1: quadratic. C1: roots 6.0 and 4.0. A1: C = 6.0 µF.', 5)
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES
('123de9ee-750b-54e8-9d4f-d29246d9653e', '2b3edb7c-d767-5cf5-aec3-f15f63158a14', 'The p.d. across each capacitor', 'A', false, 0),
('47e2dd0f-c6b6-5dc3-9d70-cce91fe19a01', '2b3edb7c-d767-5cf5-aec3-f15f63158a14', 'The energy stored in each capacitor', 'B', false, 1),
('53a2d5bf-6d0b-5c40-ae20-0e8aec2b0b6e', '2b3edb7c-d767-5cf5-aec3-f15f63158a14', 'The charge on each capacitor', 'C', true, 2),
('3f922f82-775b-5529-9a1a-099a244386ad', '2b3edb7c-d767-5cf5-aec3-f15f63158a14', 'The capacitance of each capacitor', 'D', false, 3),
('875f1fb2-6923-5f31-abbc-77de57f9fe16', 'e2af951b-577f-5dc8-b677-0068adb10d9d', '1/C = 1/C₁ + 1/C₂', 'A', true, 0),
('b04c5355-0c50-56dc-b79d-7d9aef83acd0', 'e2af951b-577f-5dc8-b677-0068adb10d9d', 'C = C₁ + C₂', 'B', false, 1),
('f7e82c18-70e5-5298-8b82-f073ec1969cf', 'e2af951b-577f-5dc8-b677-0068adb10d9d', 'C = 1/C₁ + 1/C₂', 'C', false, 2),
('cb257305-7d07-5811-9a22-3fdbac4aad7b', 'e2af951b-577f-5dc8-b677-0068adb10d9d', 'C = C₁ − C₂', 'D', false, 3),
('cba2745b-de20-52f9-a625-5fb09f7bbf84', '29882b99-eb17-5932-9181-c0d739e25ec7', 'It is greater than the largest', 'A', false, 0),
('645830d6-775c-5569-a315-410bd0456224', '29882b99-eb17-5932-9181-c0d739e25ec7', 'It equals the smallest', 'B', false, 1),
('2ce79bc5-d514-504a-9d30-5f1ba98a3e52', '29882b99-eb17-5932-9181-c0d739e25ec7', 'It equals the average', 'C', false, 2),
('4d94eab9-fe20-54e3-96bf-b27625aeaead', '29882b99-eb17-5932-9181-c0d739e25ec7', 'It is less than the smallest', 'D', true, 3),
('8c656941-393b-5e8f-9f46-e3c57e508693', '09b91411-bcf9-537e-a62f-186e0177b6c3', 'The one with the larger capacitance', 'A', false, 0),
('3bb65ff6-6417-5134-8769-03c3bdb1565a', '09b91411-bcf9-537e-a62f-186e0177b6c3', 'The one with the smaller capacitance', 'B', true, 1),
('14688ba8-054b-58f3-9f42-2478c1108e66', '09b91411-bcf9-537e-a62f-186e0177b6c3', 'They have equal p.d.s', 'C', false, 2),
('347dca2c-4e4c-5ac7-8b53-ef1fd4b8d556', '09b91411-bcf9-537e-a62f-186e0177b6c3', 'The one nearer the positive terminal', 'D', false, 3),
('d4c96c42-2f02-522e-97b0-0eb43a86b586', 'f1d17ebe-fc5a-5f8c-8244-70e25a95e71c', 'Each equals the supply p.d.', 'A', false, 0),
('c1379d8b-4b12-55fa-95d1-28cf8be199bf', 'f1d17ebe-fc5a-5f8c-8244-70e25a95e71c', 'They are all equal to zero', 'B', false, 1),
('c2f2fcb2-6955-5001-958d-3a3aa58c91af', 'f1d17ebe-fc5a-5f8c-8244-70e25a95e71c', 'They add up to the supply p.d.', 'C', true, 2),
('4194563d-c89f-5691-a0db-d1cb26e4f416', 'f1d17ebe-fc5a-5f8c-8244-70e25a95e71c', 'They multiply to give the supply p.d.', 'D', false, 3),
('83115e1a-7175-578e-9b45-745124b15a46', 'c3484878-12dc-5623-97e9-9af6daaa0d49', 'So that the supply p.d. is shared, and no single capacitor exceeds its voltage rating', 'A', true, 0),
('cd22d1ab-38cc-5341-93cb-be42fc7d659f', 'c3484878-12dc-5623-97e9-9af6daaa0d49', 'To increase the total capacitance', 'B', false, 1),
('ecc0aaec-2bb5-56e5-b6aa-0282a2f1a1b0', 'c3484878-12dc-5623-97e9-9af6daaa0d49', 'To increase the charge stored', 'C', false, 2),
('80c3d333-8070-5201-98ec-9a5c4f56cac0', 'c3484878-12dc-5623-97e9-9af6daaa0d49', 'To make the current larger', 'D', false, 3),
('2bfa5627-16ee-5f50-a97a-67a965905710', 'eac2789a-ea32-5275-9d5c-e5f368511163', 'Charge jumps across the dielectric', 'A', false, 0),
('2ca8cef4-602f-590c-bca0-ed1a989d52e7', 'eac2789a-ea32-5275-9d5c-e5f368511163', 'The supply connects to them through the dielectric', 'B', false, 1),
('a3aee9dc-ab2c-54a7-b360-3adfd86b4468', 'eac2789a-ea32-5275-9d5c-e5f368511163', 'They do not become charged', 'C', false, 2),
('6f647eb6-cfd5-5aab-9ef2-9550aa74dd8c', 'eac2789a-ea32-5275-9d5c-e5f368511163', 'Electrons move along the wire between them, leaving one plate positive and the other negative', 'D', true, 3),
('5c27c98f-05e9-5240-878f-28c5ad33c51a', 'e2e8c348-0efc-52fa-82c7-a24cc0dcc782', 'It increases', 'A', false, 0),
('5df99193-2062-5cfd-93c7-5337e0315ba8', 'e2e8c348-0efc-52fa-82c7-a24cc0dcc782', 'It decreases', 'B', true, 1),
('e8b8f217-6d87-5bad-b2d6-3a29eb2fe180', 'e2e8c348-0efc-52fa-82c7-a24cc0dcc782', 'It stays the same', 'C', false, 2),
('3f8f832f-88be-5130-b710-027ec45b8b22', 'e2e8c348-0efc-52fa-82c7-a24cc0dcc782', 'It doubles', 'D', false, 3),
